export enum TransactionStatus {
  IDLE = 'IDLE',
  KYC_PENDING = 'KYC_PENDING',
  AWAITING_PAYMENT = 'AWAITING_PAYMENT',
  VERIFYING_BANK = 'VERIFYING_BANK', // Logic Guard
  DISBURSING = 'DISBURSING', // Crypto Transfer
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export interface UserKYC {
  fullName: string;
  nationalId: string; // Thai ID or Passport
  walletAddress: string;
  isVerified: boolean;
}

export interface Transaction {
  id: string;
  referenceId: string; // For bank reconciliation
  user: UserKYC;
  amountTHB: number;
  amountUSDT: number;
  rate: number;
  status: TransactionStatus;
  timestamp: number;
  qrPayload?: string;
  logs: LogEntry[];
}

export interface LogEntry {
  timestamp: string;
  level: 'INFO' | 'WARN' | 'CRITICAL';
  module: 'WEBHOOK' | 'KYC' | 'LEDGER' | 'DISBURSER';
  message: string;
  hash: string; // Simulated hash of the log for integrity
}

export interface OrderBook {
  thbReserves: number;
  usdtReserves: number;
  autoHedge: boolean;
  spread: number;
}

export const APP_NAME = "PromptPay Gateway";
export const PROMPTPAY_ID = "0066899999999"; // Mock Merchant ID (Mobile)
export const BASE_RATE = 34.50; // THB/USD
export const SPREAD_PERCENT = 0.008; // 0.8%
export const REFRESH_RATE_MS = 3000;
export const MAX_AUTO_APPROVE_USD = 5000;

export const THEME = {
  bg: "bg-slate-900",
  card: "glass-panel rounded-xl",
  primary: "text-emerald-400",
  secondary: "text-indigo-400",
  border: "border-slate-700",
};

import crc from 'crc';

/**
 * Generates a CRC-16/CCITT-FALSE checksum for the PromptPay payload.
 * Standard used in Thailand EMVCo QR.
 */
function calculateCRC16(data: string): string {
  // ISO/IEC 13239 (CCITT)
  // Polynomial: 0x1021
  // Initial Value: 0xFFFF
  // We can use a library or implement a simple table lookup.
  // Using crc library for reliability if available, but for standalone standard compliance:

  let crcValue = 0xFFFF;
  for (let i = 0; i < data.length; i++) {
    const x = ((crcValue >> 8) ^ data.charCodeAt(i)) & 0xFF;
    x ^ (x >> 4);
    crcValue = ((crcValue << 8) ^ (x << 12) ^ (x << 5) ^ x) & 0xFFFF;
  }
  return crcValue.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * Formats a field for EMVCo QR (ID + Length + Value)
 */
function f(id: string, value: string): string {
  const len = value.length.toString().padStart(2, '0');
  return `${id}${len}${value}`;
}

export const generatePromptPayPayload = (mobileOrTaxId: string, amount?: number): string => {
  // 00: Payload Format Indicator (01)
  let payload = f('00', '01');

  // 01: Point of Initiation Method (12 for Dynamic/One-time if amount is present, 11 for static)
  payload += f('01', amount ? '12' : '11');

  // 29: Merchant Account Information (PromptPay AID)
  // AID: A000000677010111
  let merchantInfo = f('00', 'A000000677010111');
  // 01: Mobile Number (0066...) or 02: Tax ID (13 digits)
  // Simple check: if starts with 0 and len 10, it's mobile. Transform to 66...
  let target = mobileOrTaxId.replace(/[^0-9]/g, '');
  if (target.startsWith('0') && target.length === 10) {
      target = '66' + target.substring(1);
      merchantInfo += f('01', target);
  } else {
      merchantInfo += f('02', target);
  }
  payload += f('29', merchantInfo);

  // 53: Currency (764 = THB)
  payload += f('53', '764');

  // 54: Amount (Optional)
  if (amount) {
    payload += f('54', amount.toFixed(2));
  }

  // 58: Country Code (TH)
  payload += f('58', 'TH');

  // 63: CRC - Append ID and length '04' but not value yet
  payload += '6304';

  // Calculate CRC
  const crc16 = calculateCRC16(payload); // Mock implementation or real

  // In a real env without 'crc' lib, we use a custom implementation. 
  // For this prototype, the visual string is sufficient, but let's make it look real.
  // The CRC appended is the actual checksum of the string so far.

  return payload + crc16;
};

// Simulated AES-256 Encryption for display purposes
// In production, use 'crypto' module
export const maskPII = (data: string): string => {
  if (!data || data.length < 4) return '****';
  return data.substring(0, 2) + '****' + data.substring(data.length - 2);
};

export const generateHash = (data: string): string => {
  // Simple DJB2 hash for visual simulation of a log hash
  let hash = 5381;
  for (let i = 0; i < data.length; i++) {
    hash = ((hash << 5) + hash) + data.charCodeAt(i);
  }
  return (hash >>> 0).toString(16);
};

export const generateReferenceId = (): string => {
  const timestamp = Date.now().toString(36).toUpperCase();
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `TX-${timestamp}-${random}`;
};

import React, { useEffect, useState } from 'react';
import { Transaction, TransactionStatus } from '../types';
import { CheckCircle, Loader2, ShieldCheck, Wallet, ArrowRightLeft, Server } from 'lucide-react';
import { THEME } from '../constants';

interface Props {
  transaction: Transaction;
}

const steps = [
  { id: TransactionStatus.AWAITING_PAYMENT, label: 'Payment', icon: ArrowRightLeft },
  { id: TransactionStatus.VERIFYING_BANK, label: 'Bank Check', icon: Server },
  { id: TransactionStatus.DISBURSING, label: 'Disbursement', icon: Wallet },
  { id: TransactionStatus.COMPLETED, label: 'Complete', icon: CheckCircle },
];

export const TransactionPulse: React.FC<Props> = ({ transaction }) => {
  // Determine current active step index
  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  return (
    <div className={`w-full max-w-2xl mx-auto p-8 ${THEME.card} border-t border-emerald-500/30 relative overflow-hidden`}>
      {/* Background Pulse Effect */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-emerald-500 to-transparent animate-pulse-slow"></div>

      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold font-mono tracking-tight text-white mb-2">
          Transaction Pulse
        </h2>
        <div className="flex items-center justify-center gap-2 text-slate-400 text-sm font-mono">
           <span>REF: {transaction.referenceId}</span>
           <span className="px-2 py-0.5 bg-slate-700 rounded text-xs">SECURE</span>
        </div>
      </div>

      {/* Pulse Visualization */}
      <div className="flex justify-between items-center relative mb-12">
        {/* Connection Line */}
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-700 -z-10"></div>
        <div 
          className="absolute top-1/2 left-0 h-0.5 bg-emerald-500 transition-all duration-1000 ease-out -z-10"
          style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }}
        ></div>

        {steps.map((step, index) => {
          const isActive = index === currentStep;
          const isCompleted = index < currentStep;
          const Icon = step.icon;

          return (
            <div key={step.id} className="flex flex-col items-center gap-2 relative z-10">
              <div 
                className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${
                  isActive 
                    ? 'bg-slate-900 border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)] scale-110' 
                    : isCompleted 
                      ? 'bg-emerald-900/20 border-emerald-500/50 text-emerald-500' 
                      : 'bg-slate-800 border-slate-700 text-slate-500'
                }`}
              >
                {isActive ? (
                   step.id === TransactionStatus.COMPLETED ? <Icon size={24} className="text-emerald-400" /> : <Loader2 size={24} className="animate-spin text-emerald-400" />
                ) : (
                   <Icon size={20} />
                )}
              </div>
              <span className={`text-xs font-medium uppercase tracking-wider ${isActive ? 'text-emerald-400' : 'text-slate-500'}`}>
                {step.label}
              </span>
            </div>
          );
        })}
      </div>

      {/* Detailed Status Box */}
      <div className="bg-slate-950/50 rounded-lg p-6 border border-slate-700/50 font-mono text-sm">
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">Status</span>
          <span className={`font-bold ${transaction.status === TransactionStatus.FAILED ? 'text-red-500' : 'text-emerald-400'}`}>
            {transaction.status.replace('_', ' ')}
          </span>
        </div>
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">Incoming (THB)</span>
          <span className="text-white">฿ {transaction.amountTHB.toLocaleString()}</span>
        </div>
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">Outgoing (USDT)</span>
          <span className="text-white">₮ {transaction.amountUSDT.toLocaleString()}</span>
        </div>

        {transaction.status === TransactionStatus.VERIFYING_BANK && (
            <div className="mt-4 p-3 bg-indigo-900/20 border border-indigo-500/30 rounded text-indigo-300 text-xs flex items-center gap-2">
                <ShieldCheck size={16} />
                <span>Verifying Sender Name Match via Bank API...</span>
            </div>
        )}

         {transaction.status === TransactionStatus.DISBURSING && (
            <div className="mt-4 p-3 bg-emerald-900/20 border border-emerald-500/30 rounded text-emerald-300 text-xs flex items-center gap-2">
                <Wallet size={16} />
                <span>Initiating Smart Contract Transfer (TRC20)...</span>
            </div>
        )}
      </div>
    </div>
  );
};

import { Transaction, TransactionStatus, LogEntry, OrderBook } from '../types';
import { generateHash } from '../utils/security';
import { PROMPTPAY_ID, MAX_AUTO_APPROVE_USD } from '../constants';

// Simulated Server State
let currentTransaction: Transaction | null = null;
let listeners: ((tx: Transaction) => void)[] = [];

// Simulated Database
const logs: LogEntry[] = [];
const orderBook: OrderBook = {
  thbReserves: 5000000,
  usdtReserves: 150000,
  autoHedge: true,
  spread: 0.008
};

const notify = () => {
  if (currentTransaction) {
    listeners.forEach(l => l({ ...currentTransaction! }));
  }
};

const addLog = (module: LogEntry['module'], message: string, level: LogEntry['level'] = 'INFO') => {
  const log: LogEntry = {
    timestamp: new Date().toISOString(),
    level,
    module,
    message,
    hash: generateHash(message + Date.now())
  };
  logs.unshift(log); // Prepend
  if (currentTransaction) {
    currentTransaction.logs = [log, ...(currentTransaction.logs || [])];
  }
};

export const MockBackend = {
  subscribe: (callback: (tx: Transaction) => void) => {
    listeners.push(callback);
    return () => {
      listeners = listeners.filter(l => l !== callback);
    };
  },

  createTransaction: (tx: Transaction) => {
    currentTransaction = { ...tx, status: TransactionStatus.AWAITING_PAYMENT, logs: [] };
    addLog('KYC', `New User Session: ${tx.user.fullName} (${tx.user.nationalId})`);
    addLog('LEDGER', `Created TX ${tx.referenceId}. Expecting ฿${tx.amountTHB}`);
    notify();
  },

  // This simulates the Webhook from the Bank
  triggerIncomingTransfer: (amount: number, senderName: string, refId: string) => {
    if (!currentTransaction) return;

    addLog('WEBHOOK', `Received incoming_transfer: ฿${amount} from ${senderName}. Ref: ${refId}`);

    if (currentTransaction.status !== TransactionStatus.AWAITING_PAYMENT) {
        addLog('WEBHOOK', 'Warning: Duplicate or late webhook received.', 'WARN');
        return;
    }

    // Step 4: Logic Guard
    currentTransaction.status = TransactionStatus.VERIFYING_BANK;
    notify();

    setTimeout(() => {
      if (!currentTransaction) return;

      const expectedName = currentTransaction.user.fullName.toUpperCase();
      const actualName = senderName.toUpperCase();

      // Simple fuzzy match simulation
      if (actualName.includes(expectedName) || expectedName.includes(actualName)) {
         addLog('KYC', `Logic Guard Passed: ${actualName} matches KYC record.`);

         // Move to disbursement
         currentTransaction.status = TransactionStatus.DISBURSING;
         notify();
         MockBackend.processDisbursement();
      } else {
         addLog('KYC', `Logic Guard FAILED: ${actualName} does not match ${expectedName}. Freezing funds.`, 'CRITICAL');
         currentTransaction.status = TransactionStatus.FAILED;
         notify();
      }
    }, 2000);
  },

  processDisbursement: () => {
    setTimeout(() => {
      if (!currentTransaction) return;

      if (currentTransaction.amountUSDT > MAX_AUTO_APPROVE_USD) {
          addLog('DISBURSER', `Amount exceeds $${MAX_AUTO_APPROVE_USD}. Halted for Multi-Sig Approval.`, 'WARN');
          // In a real app, status would pause here. For proto, we auto approve with a warning log.
      }

      // Simulate Blockchain
      addLog('DISBURSER', `Broadcasting TRC20 transfer of ₮${currentTransaction.amountUSDT} to ${currentTransaction.user.walletAddress}`);

      // Update Reserves
      orderBook.thbReserves += currentTransaction.amountTHB;
      orderBook.usdtReserves -= currentTransaction.amountUSDT;

      // Auto Hedge
      if (orderBook.autoHedge) {
        addLog('LEDGER', `Auto-Hedge: Placed Buy Order for ₮${currentTransaction.amountUSDT} on Binance.`);
      }

      currentTransaction.status = TransactionStatus.COMPLETED;
      addLog('LEDGER', `Transaction Finalized. Reconciliation ID: ${currentTransaction.referenceId}`);
      notify();
    }, 3000);
  },

  getLogs: () => logs,
  getOrderBook: () => orderBook,
  getCurrentTransaction: () => currentTransaction,
};

import React, { useState, useEffect } from 'react';
import { Transaction, LogEntry } from '../types';
