        <div className="flex items-center gap-2">
            <span className="text-xs text-slate-400 font-mono">SEC_AUDIT_MODE: ENABLED</span>
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Col: Liquidity & Controls */}
        <div className="lg:col-span-2 space-y-6">
            {/* Stats */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-950 p-4 rounded border border-slate-800">
                    <div className="text-slate-400 text-xs mb-1">THB Reserves (Bank)</div>
                    <div className="text-2xl font-mono font-bold text-emerald-400">฿ {reserves.thbReserves.toLocaleString()}</div>
                </div>
                <div className="bg-slate-950 p-4 rounded border border-slate-800">
                    <div className="text-slate-400 text-xs mb-1">USDT Float (Hot Wallet)</div>
                    <div className="text-2xl font-mono font-bold text-indigo-400">₮ {reserves.usdtReserves.toLocaleString()}</div>
                </div>
            </div>

            {/* Chart */}
            <div className="h-64 bg-slate-950/50 rounded border border-slate-800 p-2">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={data}>
                        <XAxis dataKey="name" stroke="#475569" fontSize={12} />
                        <YAxis stroke="#475569" fontSize={12} />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }}
                            itemStyle={{ color: '#fff' }}
                        />
                        <Bar dataKey="thb" fill="#10b981" radius={[4, 4, 0, 0]} />
                        <Bar dataKey="usdt" fill="#6366f1" radius={[4, 4, 0, 0]} />
                    </BarChart>
                </ResponsiveContainer>
            </div>

            {/* Webhook Simulator (Dev Tool) */}
            <div className="p-4 bg-slate-800/50 border border-slate-600 rounded-lg">
                <h4 className="text-sm font-bold text-white mb-3 flex items-center gap-2">
                    <RefreshCw size={14} /> Bank Webhook Simulator
                </h4>
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={simName} 
                        onChange={(e) => setSimName(e.target.value)}
                        className="bg-slate-950 border border-slate-700 text-white px-3 py-2 rounded text-sm flex-1"
                        placeholder="Sender Name"
                    />
                     <input 
                        type="number" 
                        value={simAmount} 
                        onChange={(e) => setSimAmount(Number(e.target.value))}
