                        className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded text-sm font-bold transition-colors"
                    >
                        Trigger Webhook
                    </button>
                </div>
                <p className="text-xs text-slate-500 mt-2">
                    Simulates `POST /webhook/scb` with payload matching current transaction.
                </p>
            </div>
        </div>

        {/* Right Col: Logs */}
        <div className="bg-slate-950 rounded border border-slate-800 flex flex-col h-[500px]">
            <div className="p-3 border-b border-slate-800 flex justify-between items-center bg-slate-900">
