import React, { useEffect, useState } from 'react';
import { Transaction, TransactionStatus } from '../types';
import { CheckCircle, Loader2, ShieldCheck, Wallet, ArrowRightLeft, Server, AlertTriangle, XCircle } from 'lucide-react';
import { THEME } from '../constants';

interface Props {
  transaction: Transaction;
}

const steps = [
  { id: TransactionStatus.AWAITING_PAYMENT, label: 'Payment', icon: ArrowRightLeft },
  { id: TransactionStatus.VERIFYING_BANK, label: 'Bank Check', icon: Server },
  { id: TransactionStatus.DISBURSING, label: 'Disbursement', icon: Wallet },
  { id: TransactionStatus.COMPLETED, label: 'Complete', icon: CheckCircle },
];

export const TransactionPulse: React.FC<Props> = ({ transaction }) => {
  const isFailed = transaction.status === TransactionStatus.FAILED;

  // Determine current active step index
  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      // If failed, we visualize it stopping at the Bank Check (Logic Guard) stage for this prototype
      case TransactionStatus.FAILED: return 1; 
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  // Extract failure reason from logs if failed
  const failureReason = isFailed 
    ? (transaction.logs.find(l => l.level === 'CRITICAL')?.message || 'Compliance checks failed.') 
    : null;

  return (
    <div className={`w-full max-w-2xl mx-auto p-8 ${THEME.card} ${isFailed ? 'border-t-red-500/50 shadow-[0_0_20px_rgba(239,68,68,0.15)]' : 'border-t-emerald-500/30'} relative overflow-hidden transition-all duration-500`}>
      {/* Background Pulse Effect */}
      <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent ${isFailed ? 'via-red-500' : 'via-emerald-500'} to-transparent animate-pulse-slow`}></div>

      <div className="text-center mb-8">
        <h2 className={`text-2xl font-bold font-mono tracking-tight ${isFailed ? 'text-red-500' : 'text-white'} mb-2`}>
          {isFailed ? 'Transaction Failed' : 'Transaction Pulse'}
        </h2>
        <div className="flex items-center justify-center gap-2 text-slate-400 text-sm font-mono">
           <span>REF: {transaction.referenceId}</span>
           <span className={`px-2 py-0.5 rounded text-xs ${isFailed ? 'bg-red-950 text-red-400 border border-red-900' : 'bg-slate-700 text-slate-300'}`}>
             {isFailed ? 'REJECTED' : 'SECURE'}
           </span>
        </div>
      </div>

      {/* Pulse Visualization */}
      <div className="flex justify-between items-center relative mb-12">
        {/* Connection Line */}
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-700 -z-10"></div>
        <div 
          className={`absolute top-1/2 left-0 h-0.5 ${isFailed ? 'bg-red-500' : 'bg-emerald-500'} transition-all duration-1000 ease-out -z-10`}
          style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }}
        ></div>

        {steps.map((step, index) => {
          const isActive = index === currentStep;
          const isCompleted = index < currentStep;
          const Icon = step.icon;

          let circleClass = 'bg-slate-800 border-slate-700 text-slate-500';
          if (isActive) {
             if (isFailed) {
                 circleClass = 'bg-red-950/80 border-red-500 text-red-500 shadow-[0_0_15px_rgba(239,68,68,0.6)] scale-110';
             } else {
                 circleClass = 'bg-slate-900 border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)] scale-110';
             }
          } else if (isCompleted) {
             circleClass = 'bg-emerald-900/20 border-emerald-500/50 text-emerald-500';
          }

          return (
            <div key={step.id} className="flex flex-col items-center gap-2 relative z-10">
              <div 
                className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${circleClass}`}
              >
                {isActive ? (
                   isFailed ? <XCircle size={24} className="text-red-500" /> :
