/**
 * Generates a CRC-16/CCITT-FALSE checksum for the PromptPay payload.
 * Standard used in Thailand EMVCo QR.
 * Polynomial: 0x1021, Initial: 0xFFFF
 */
function calculateCRC16(data: string): string {
  let crc = 0xFFFF;
  for (let i = 0; i < data.length; i++) {
    let x = ((crc >> 8) ^ data.charCodeAt(i)) & 0xFF;
    x ^= x >> 4;
    crc = ((crc << 8) ^ (x << 12) ^ (x << 5) ^ x) & 0xFFFF;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * Formats a field for EMVCo QR (ID + Length + Value)
 */
function f(id: string, value: string): string {
  const len = value.length.toString().padStart(2, '0');
  return `${id}${len}${value}`;
}

export const generatePromptPayPayload = (target: string, amount?: number): string => {
  // 1. Sanitize Input
  let sanitized = target.replace(/[^0-9]/g, '');
  let merchantAccountInfo = f('00', 'A000000677010111'); // AID for PromptPay

  // 2. Determine Target Type (Mobile vs Tax ID vs E-Wallet) & Format Correctly
  // Rules:
  // - Mobile (Tag 01): Must start with 0066. 
  //   Inputs often come as 0812345678 (10 digit) or 66812345678.
  // - Tax/ID (Tag 02): 13 digits.
  // - E-Wallet (Tag 03): 15 digits.

  if (sanitized.length === 10 && sanitized.startsWith('0')) {
      // Case: Standard Mobile 08x... -> Convert to 00668x...
      const formattedMobile = '0066' + sanitized.substring(1);
      merchantAccountInfo += f('01', formattedMobile);
  } else if (sanitized.length === 11 && sanitized.startsWith('66')) {
      // Case: International Mobile 668x... -> Convert to 00668x...
      const formattedMobile = '00' + sanitized;
      merchantAccountInfo += f('01', formattedMobile);
  } else if (sanitized.length === 13 && sanitized.startsWith('0066')) {
      // Case: Already formatted PromptPay Mobile
      merchantAccountInfo += f('01', sanitized);
  } else if (sanitized.length === 13) {
      // Case: Tax ID or National ID
      merchantAccountInfo += f('02', sanitized);
  } else if (sanitized.length === 15) {
      // Case: E-Wallet ID
      merchantAccountInfo += f('03', sanitized);
  } else {
      // Fallback: Default to Tax ID tag if length is weird, or just pass as is
      merchantAccountInfo += f('02', sanitized);
  }

  // 3. Construct Payload
  // 00: Payload Format Indicator (01)
  let payload = f('00', '01');

  // 01: Point of Initiation Method (12 for Dynamic/One-time if amount is present, 11 for static)
  payload += f('01', amount ? '12' : '11');

  // 29: Merchant Account Information
  payload += f('29', merchantAccountInfo);

  // 53: Currency (764 = THB)
  payload += f('53', '764');

  // 54: Amount (Optional)
  if (amount) {
    payload += f('54', amount.toFixed(2));
  }

  // 58: Country Code (TH)
  payload += f('58', 'TH');

  // 63: CRC - Append ID and length '04'
  payload += '6304';

  // 4. Calculate and Append CRC
  return payload + calculateCRC16(payload);
};

