/**
 * Standard CRC16-CCITT implementation for EMVCo QR Codes.
 * Polynomial: 0x1021, Initial Value: 0xFFFF
 */
function calculateCRC16(data: string): string {
  let crc = 0xFFFF;
  for (let i = 0; i < data.length; i++) {
    let x = ((crc >> 8) ^ data.charCodeAt(i)) & 0xFF;
    x ^= x >> 4;
    crc = ((crc << 8) ^ (x << 12) ^ (x << 5) ^ x) & 0xFFFF;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * Helper to format TLV (Tag-Length-Value) objects
 */
function f(id: string, value: string): string {
  const len = value.length.toString().padStart(2, '0');
  return `${id}${len}${value}`;
}

/**
 * Analyzes the input ID and returns the correct EMV tag and formatted value.
 * Supports:
 * - Mobile (08x, 09x, 06x) -> Tag 01 (Prefix 0066)
 * - National/Tax ID (13 digits) -> Tag 02
 * - E-Wallet (15 digits) -> Tag 03
 */
function getTargetTypeAndValue(target: string): { tag: string; value: string } {
  const raw = target.replace(/[^0-9]/g, '');

  // Case 1: Mobile Number (10 digits starting with 0) -> Format to 0066...
  if (raw.length === 10 && raw.startsWith('0')) {
    return { tag: '01', value: `0066${raw.substring(1)}` };
  }

  // Case 2: Mobile Number (11 digits starting with 66) -> Format to 0066...
  if (raw.length === 11 && raw.startsWith('66')) {
    return { tag: '01', value: `00${raw}` };
  }

  // Case 3: Already formatted Mobile (13 digits starting with 0066)
  if (raw.length === 13 && raw.startsWith('0066')) {
    return { tag: '01', value: raw };
  }

  // Case 4: National ID / Tax ID (13 digits)
  if (raw.length === 13) {
    return { tag: '02', value: raw };
  }

  // Case 5: E-Wallet (15 digits)
  if (raw.length === 15) {
    return { tag: '03', value: raw };
  }

  // Fallback: Return raw as National ID if undefined, or throw error in stricter env
  // For prototype, we default to Tag 02 if it looks vaguely like an ID
  return { tag: '02', value: raw };
}

export const generatePromptPayPayload = (target: string, amount?: number): string => {
  const { tag, value } = getTargetTypeAndValue(target);

  // 1. Build Merchant Account Information (Tag 29)
  //    - Tag 00: AID (A000000677010111)
  //    - Tag 01/02/03: Target Value
  let merchantInfo = f('00', 'A000000677010111');
  merchantInfo += f(tag, value);

  // 2. Build Root Tags
  const tags = [
    f('00', '01'),                        // Payload Format Indicator
    f('01', amount ? '12' : '11'),        // Point of Initiation (12 = Dynamic, 11 = Static)
    f('29', merchantInfo),                // Merchant Account Info
    f('53', '764'),                       // Transaction Currency (THB)
    amount ? f('54', amount.toFixed(2)) : '', // Transaction Amount (Optional)
    f('58', 'TH'),                        // Country Code
  ];

  // 3. Assemble Data & Append CRC Checksum
  const rawData = tags.join('') + '6304'; // Append CRC Tag ID and Length
  const crc = calculateCRC16(rawData);

  return rawData + crc;
};

