        {/* Connection Line */}
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-700 -z-10"></div>
        <div 
          className={`absolute top-1/2 left-0 h-0.5 ${isFailed ? 'bg-red-500' : 'bg-emerald-500'} transition-all duration-1000 ease-out -z-10`}
          style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }}
        ></div>

        {steps.map((step, index) => {
          const isActive = index === currentStep;
          const isCompleted = index < currentStep;
          const Icon = step.icon;

          let circleClass = 'bg-slate-800 border-slate-700 text-slate-500';
          if (isActive) {
             if (isFailed) {
                 circleClass = 'bg-red-950/80 border-red-500 text-red-500 shadow-[0_0_15px_rgba(239,68,68,0.6)] scale-110';
             } else {
                 circleClass = 'bg-slate-900 border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)] scale-110';
             }
          } else if (isCompleted) {
             circleClass = 'bg-emerald-900/20 border-emerald-500/50 text-emerald-500';
          }

          return (
            <div key={step.id} className="flex flex-col items-center gap-2 relative z-10">
              <div 
                className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${circleClass}`}
              >
                {isActive ? (
                   isFailed ? <XCircle size={24} className="text-red-500" /> :
                   step.id === TransactionStatus.COMPLETED ? <Icon size={24} className="text-emerald-400" /> : <Loader2 size={24} className="animate-spin text-emerald-400" />
                ) : (
                   <Icon size={20} />
                )}
              </div>
              <span className={`text-xs font-medium uppercase tracking-wider ${isActive ? (isFailed ? 'text-red-400' : 'text-emerald-400') : 'text-slate-500'}`}>
                {step.label}
              </span>
            </div>
          );
        })}
      </div>

      {/* Detailed Status Box */}
      <div className={`rounded-lg p-6 border font-mono text-sm transition-colors duration-500 ${isFailed ? 'bg-red-950/10 border-red-900/50' : 'bg-slate-950/50 border-slate-700/50'}`}>
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">{t.status}</span>
          <span className={`font-bold ${isFailed ? 'text-red-500' : 'text-emerald-400'}`}>
            {transaction.status.replace('_', ' ')}
          </span>
        </div>
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">{t.incoming}</span>
          <span className="text-white">฿ {transaction.amountTHB.toLocaleString()}</span>
        </div>
        <div className="flex justify-between mb-2">
          <span className="text-slate-400">{t.outgoing}</span>
          <span className="text-white">₮ {transaction.amountUSDT.toLocaleString()}</span>
        </div>

        {/* Contextual Status Messages */}
        {transaction.status === TransactionStatus.VERIFYING_BANK && !isFailed && (
            <div className="mt-4 p-3 bg-indigo-900/20 border border-indigo-500/30 rounded text-indigo-300 text-xs flex items-center gap-2">
                <ShieldCheck size={16} />
                <span>{t.verifying}</span>
            </div>
        )}

         {transaction.status === TransactionStatus.DISBURSING && !isFailed && (
            <div className="mt-4 p-3 bg-emerald-900/20 border border-emerald-500/30 rounded text-emerald-300 text-xs flex items-center gap-2">
                <Wallet size={16} />
                <span>{t.initiating}</span>
            </div>
        )}

        {/* Failure Reason */}
        {isFailed && (
            <div className="mt-4 p-3 bg-red-900/20 border border-red-500/30 rounded text-red-200 text-xs flex items-start gap-3 animate-pulse">
                <AlertTriangle size={18} className="shrink-0 mt-0.5" />
                <div className="flex flex-col">
                    <span className="font-bold text-red-400 uppercase tracking-wide mb-1">{t.alert}</span>
                    <span>{failureReason}</span>
                    <span className="mt-2 text-red-500/70">{t.contactSupport}</span>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

