                  <div className="flex flex-col justify-center space-y-4">
                      <div className="bg-slate-800/50 p-4 rounded-lg border-l-4 border-yellow-500">
                          <h4 className="text-white font-bold mb-1">{t.dontClose}</h4>
                          <p className="text-slate-400 text-sm">{t.listening}</p>
                      </div>
                       <div className="bg-slate-800/50 p-4 rounded-lg border-l-4 border-indigo-500">
                          <h4 className="text-white font-bold mb-1">{t.exactAmount}</h4>
                          <p className="text-slate-400 text-sm">{t.transferExactly} <span className="text-white font-mono">฿{activeTx.amountTHB.toFixed(2)}</span></p>
                      </div>
                  </div>
               </div>
             )}
          </div>
        )}

