/**
 * Standard CRC16-CCITT-FALSE implementation for EMVCo QR Codes.
 * Polynomial: 0x1021
 * Initial Value: 0xFFFF
 * This algorithm is required by the PromptPay / EMVCo standard.
 */
function calculateCRC16(data: string): string {
  let crc = 0xFFFF;
  for (let i = 0; i < data.length; i++) {
    // XOR byte into the top of the CRC register
    let x = ((crc >> 8) ^ data.charCodeAt(i)) & 0xFF;
    // Standard CCITT-FALSE bitwise operations
    x ^= x >> 4;
    crc = ((crc << 8) ^ (x << 12) ^ (x << 5) ^ x) & 0xFFFF;
  }
  // Return as 4-digit Uppercase Hex
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * Helper to format TLV (Tag-Length-Value) objects
 */
function f(id: string, value: string): string {
  const len = value.length.toString().padStart(2, '0');
  return `${id}${len}${value}`;
}

/**
 * Analyzes the input ID and returns the correct EMV tag and formatted value.
 * Supports:
 * - Mobile (08x, 09x, 06x) -> Tag 01 (Prefix 0066)
 * - National/Tax ID (13 digits) -> Tag 02
 * - E-Wallet (15 digits) -> Tag 03
 */
function getTargetTypeAndValue(target: string): { tag: string; value: string } {
  const raw = target.replace(/[^0-9]/g, '');

  // Case 1: Mobile Number (10 digits starting with 0) -> Format to 0066...
  if (raw.length === 10 && raw.startsWith('0')) {
    return { tag: '01', value: `0066${raw.substring(1)}` };
  }

  // Case 2: Mobile Number (11 digits starting with 66) -> Format to 0066...
  if (raw.length === 11 && raw.startsWith('66')) {
    return { tag: '01', value: `00${raw}` };
  }

  // Case 3: Already formatted Mobile (13 digits starting with 0066)
  if (raw.length === 13 && raw.startsWith('0066')) {
    return { tag: '01', value: raw };
  }

  // Case 4: National ID / Tax ID (13 digits)
  if (raw.length === 13) {
    return { tag: '02', value: raw };
  }

  // Case 5: E-Wallet (15 digits)
  if (raw.length === 15) {
    return { tag: '03', value: raw };
  }

  // Fallback: Return raw as National ID if undefined
  return { tag: '02', value: raw };
}

export const generatePromptPayPayload = (target: string, amount?: number): string => {
  const { tag, value } = getTargetTypeAndValue(target);

  // 1. Build Merchant Account Information (Tag 29)
  //    - Tag 00: AID (A000000677010111)
  //    - Tag 01/02/03: Target Value
  let merchantInfo = f('00', 'A000000677010111');
  merchantInfo += f(tag, value);

  // 2. Build Root Tags
  const tags = [
    f('00', '01'),                        // Payload Format Indicator
    f('01', amount ? '12' : '11'),        // Point of Initiation (12 = Dynamic, 11 = Static)
    f('29', merchantInfo),                // Merchant Account Info
    f('53', '764'),                       // Transaction Currency (THB)
    amount ? f('54', amount.toFixed(2)) : '', // Transaction Amount (Optional)
    f('58', 'TH'),                        // Country Code
  ];

  // 3. Assemble Data & Append CRC Placeholder
  // Important: We must append the Checksum ID ('63') and Length ('04') 
  // BEFORE calculating the checksum of the entire string.
  const rawData = tags.join('') + '6304'; 

  // 4. Calculate CRC16-CCITT (0x1021)
  const crc = calculateCRC16(rawData);

  // 5. Return Full Payload
  return rawData + crc;
};

/**
 * Standard CRC16-CCITT implementation for EMVCo QR Codes (PromptPay).
 * 
 * Algorithm Details:
 * - Polynomial: 0x1021 (CCITT)
 * - Initial Value: 0xFFFF
 * - XOR Output: 0x0000
 * - Reflected In/Out: False
 */
function calculateCRC16(data: string): string {
  let crc = 0xFFFF; // Initial value

  for (let i = 0; i < data.length; i++) {
    // XOR byte into the top of the CRC register
    let x = ((crc >> 8) ^ data.charCodeAt(i)) & 0xFF;

    // Standard CCITT-FALSE bitwise operations for Poly 0x1021
    x ^= x >> 4;
    crc = ((crc << 8) ^ (x << 12) ^ (x << 5) ^ x) & 0xFFFF;
  }

  // Return as 4-digit Uppercase Hex
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * Helper to format TLV (Tag-Length-Value) objects according to EMVCo spec.
 * - ID: 2 digits
 * - Length: 2 digits (zero padded)
 * - Value: String data
 */
function f(id: string, value: string): string {
  const len = value.length.toString().padStart(2, '0');
  return `${id}${len}${value}`;
}

/**
 * Analyzes the input ID and returns the correct EMV tag and formatted value.
 * Sanitizes input by removing dashes or spaces.
 * 
 * Logic:
 * - Mobile (Tag 01): Formats local 08x to 00668x
 * - National ID (Tag 02): 13 digits
 * - E-Wallet (Tag 03): 15 digits
 */
function getTargetTypeAndValue(target: string): { tag: string; value: string } {
  // 1. Sanitize: Remove all non-numeric characters
  const raw = target.replace(/\D/g, '');

  // Case 1: Mobile Number (Local Format)
  // Input: 0812345678 (10 digits, starts with 0)
  // Output: 0066812345678
  if (raw.length === 10 && raw.startsWith('0')) {
    return { tag: '01', value: `0066${raw.substring(1)}` };
  }

  // Case 2: Mobile Number (International Format without 00)
  // Input: 66812345678 (11 digits, starts with 66)
  // Output: 0066812345678
  if (raw.length === 11 && raw.startsWith('66')) {
    return { tag: '01', value: `00${raw}` };
  }

  // Case 3: Mobile Number (Full EMV Format)
  // Input: 0066812345678 (13 digits, starts with 0066)
  if (raw.length === 13 && raw.startsWith('0066')) {
    return { tag: '01', value: raw };
  }

  // Case 4: National ID / Tax ID
  // Input: 1234567890123 (13 digits)
  if (raw.length === 13) {
    return { tag: '02', value: raw };
  }

  // Case 5: E-Wallet
  // Input: 15 digits typically
  if (raw.length === 15) {
    return { tag: '03', value: raw };
  }

  // Fallback: Default to National ID (Tag 02) if length doesn't match specific rules
  // This allows manual entry of IDs that might not strictly follow the lengths above but are intended as Tax IDs.
  return { tag: '02', value: raw };
}

/**
 * Generates the full EMVCo QR Payload string.
 * @param target The PromptPay ID (Mobile, ID Card, or E-Wallet)
 * @param amount Optional transaction amount (THB)
 */
export const generatePromptPayPayload = (target: string, amount?: number): string => {
  const { tag, value } = getTargetTypeAndValue(target);

  // 1. Build Merchant Account Information (Tag 29)
  //    - Tag 00: AID (A000000677010111 is the PromptPay AID)
  //    - Tag 01/02/03: The target ID value calculated above
  let merchantInfo = f('00', 'A000000677010111');
  merchantInfo += f(tag, value);

  // 2. Build Root Tags
  // Tag 54 (Amount) is optional in standard, but usually required for "Dynamic QR"
  const tags = [
    f('00', '01'),                        // Payload Format Indicator (01)
    f('01', amount ? '12' : '11'),        // Point of Initiation (12 = Dynamic/Amount, 11 = Static)
    f('29', merchantInfo),                // Merchant Account Info (Application ID + Target)
    f('53', '764'),                       // Transaction Currency (764 = THB)
    amount ? f('54', amount.toFixed(2)) : '', // Transaction Amount (2 decimal places)
    f('58', 'TH'),                        // Country Code
  ];

  // 3. Assemble Data & Append CRC Placeholder
  // The CRC calculation includes the CRC Tag ID ('63') and Length ('04') at the end.
  const rawData = tags.join('') + '6304'; 

  // 4. Calculate CRC16-CCITT (0x1021) of the rawData string
  const crc = calculateCRC16(rawData);

  // 5. Append checksum to complete the payload
  return rawData + crc;
};

import { Transaction, TransactionStatus, LogEntry, OrderBook } from '../types';
import { generateHash } from '../utils/security';
import { PROMPTPAY_ID, MAX_AUTO_APPROVE_USD } from '../constants';

// Simulated Server State
let currentTransaction: Transaction | null = null;
const transactionHistory: Transaction[] = []; // Store history
let listeners: ((tx: Transaction) => void)[] = [];

// Simulated Database
const logs: LogEntry[] = [];
const orderBook: OrderBook = {
  thbReserves: 5000000,
  usdtReserves: 150000,
  autoHedge: true,
  spread: 0.008
};

const notify = () => {
  if (currentTransaction) {
    listeners.forEach(l => l({ ...currentTransaction! }));
  }
};

const addLog = (module: LogEntry['module'], message: string, level: LogEntry['level'] = 'INFO') => {
  const log: LogEntry = {
    timestamp: new Date().toISOString(),
    level,
    module,
    message,
    hash: generateHash(message + Date.now())
  };
  logs.unshift(log); // Prepend
  if (currentTransaction) {
    currentTransaction.logs = [log, ...(currentTransaction.logs || [])];
  }
};

export const MockBackend = {
  subscribe: (callback: (tx: Transaction) => void) => {
    listeners.push(callback);
    return () => {
      listeners = listeners.filter(l => l !== callback);
    };
  },

  createTransaction: (tx: Transaction) => {
    currentTransaction = { ...tx, status: TransactionStatus.AWAITING_PAYMENT, logs: [] };
    transactionHistory.unshift(currentTransaction); // Add to history
    addLog('KYC', `New User Session: ${tx.user.fullName} (${tx.user.nationalId})`);
    addLog('LEDGER', `Created TX ${tx.referenceId}. Expecting ฿${tx.amountTHB}`);
    notify();
  },

  // This simulates the Webhook from the Bank
  triggerIncomingTransfer: (amount: number, senderName: string, refId: string) => {
    if (!currentTransaction) return;

    addLog('WEBHOOK', `Received incoming_transfer: ฿${amount} from ${senderName}. Ref: ${refId}`);

    if (currentTransaction.status !== TransactionStatus.AWAITING_PAYMENT) {
        addLog('WEBHOOK', 'Warning: Duplicate or late webhook received.', 'WARN');
        return;
    }

    // Step 4: Logic Guard
    currentTransaction.status = TransactionStatus.VERIFYING_BANK;
    notify();

    setTimeout(() => {
      if (!currentTransaction) return;

      const expectedName = currentTransaction.user.fullName.toUpperCase();
      const actualName = senderName.toUpperCase();

      // Simple fuzzy match simulation
      if (actualName.includes(expectedName) || expectedName.includes(actualName)) {
         addLog('KYC', `Logic Guard Passed: ${actualName} matches KYC record.`);

         // Move to disbursement
         currentTransaction.status = TransactionStatus.DISBURSING;
         notify();
         MockBackend.processDisbursement();
      } else {
         addLog('KYC', `Logic Guard FAILED: ${actualName} does not match ${expectedName}. Freezing funds.`, 'CRITICAL');
         currentTransaction.status = TransactionStatus.FAILED;
         notify();
      }
    }, 2000);
  },

  processDisbursement: () => {
    setTimeout(() => {
      if (!currentTransaction) return;

      if (currentTransaction.amountUSDT > MAX_AUTO_APPROVE_USD) {
          addLog('DISBURSER', `Amount exceeds $${MAX_AUTO_APPROVE_USD}. Halted for Multi-Sig Approval.`, 'WARN');
          // In a real app, status would pause here. For proto, we auto approve with a warning log.
      }

      // Simulate Blockchain
      addLog('DISBURSER', `Broadcasting TRC20 transfer of ₮${currentTransaction.amountUSDT} to ${currentTransaction.user.walletAddress}`);

      // Update Reserves
      orderBook.thbReserves += currentTransaction.amountTHB;
      orderBook.usdtReserves -= currentTransaction.amountUSDT;

      // Auto Hedge Logic
      if (orderBook.autoHedge) {
        addLog('LEDGER', `Auto-Hedge: Placed Buy Order for ₮${currentTransaction.amountUSDT} on Binance.`);
      } else {
        addLog('LEDGER', `Auto-Hedge Skipped (Manual Mode). Reserves may unbalance.`);
      }

      currentTransaction.status = TransactionStatus.COMPLETED;
      addLog('LEDGER', `Transaction Finalized. Reconciliation ID: ${currentTransaction.referenceId}`);
      notify();
    }, 3000);
  },

  toggleAutoHedge: () => {
    orderBook.autoHedge = !orderBook.autoHedge;
    addLog('LEDGER', `Auto-Hedge Logic switched to ${orderBook.autoHedge ? 'ON' : 'OFF'}`, 'WARN');
  },

  getLogs: () => logs,
  getOrderBook: () => orderBook,
  getCurrentTransaction: () => currentTransaction,
  getTransactionHistory: () => transactionHistory, // Expose history
};

