  const [simError, setSimError] = useState<string | null>(null);

  useEffect(() => {
    const interval = setInterval(() => {
      setLogs([...MockBackend.getLogs()]);
      setReserves({...MockBackend.getOrderBook()});
      setActiveTx(MockBackend.getCurrentTransaction());
      setHistory([...MockBackend.getTransactionHistory()]);

      const current = MockBackend.getCurrentTransaction();
      if (current) {
         // Only auto-fill if the user hasn't typed anything custom to prevent overwriting while typing
         // For simplicity in this prototype, we'll just track if we have a current tx and if inputs match default
         if (simName === 'John Doe' && simAmount === 1000) {
            setSimName(current.user.fullName || 'John Doe');
            setSimAmount(current.amountTHB || 1000);
         }
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [simName, simAmount]); // Added deps to prevent loop overwrite if user is typing

  const triggerWebhook = () => {
    setSimError(null);

    if (!activeTx) {
        setSimError("No active transaction to trigger webhook for.");
        return;
    }

    if (!simName || simName.trim().length === 0) {
        setSimError("Sender Name cannot be empty.");
        return;
    }

    if (simAmount <= 0 || isNaN(simAmount)) {
        setSimError("Amount must be a positive number.");
        return;
    }

    MockBackend.triggerIncomingTransfer(simAmount, simName, activeTx.referenceId);
  };

  const toggleHedge = () => {
    MockBackend.toggleAutoHedge();
    setReserves({...MockBackend.getOrderBook()});
  };

  // Filter for completed or failed transactions
  const completedHistory = history.filter(tx => 
    tx.status === TransactionStatus.COMPLETED || tx.status === TransactionStatus.FAILED
  );

  return (
    <div className={`mt-12 p-6 ${THEME.card} border-slate-700`}>
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-xl font-bold text-white flex items-center gap-2">
