                    <div className="text-2xl font-mono font-bold text-emerald-400">฿ {reserves.thbReserves.toLocaleString()}</div>
                </div>
                <div className="bg-slate-950 p-4 rounded border border-slate-800">
                    <div className="text-slate-400 text-xs mb-1">{t.usdtFloat}</div>
                    <div className="text-2xl font-mono font-bold text-indigo-400">₮ {reserves.usdtReserves.toLocaleString()}</div>
                </div>
            </div>

            {/* Auto Hedge Toggle */}
