                        <Zap size={18} />
                    </div>
                    <div className="flex flex-col">
                        <span className="text-sm font-bold text-slate-200">Auto-Hedge Algorithm</span>
                        <span className="text-[10px] text-slate-500">Automatically rebalance USDT float via Binance API</span>
                    </div>
                </div>
                <button 
                    onClick={toggleHedge}
                    className={`relative w-12 h-6 rounded-full transition-colors duration-300 ${reserves.autoHedge ? 'bg-emerald-500/20 border-emerald-500/50' : 'bg-slate-800 border-slate-600'} border`}
