                       ))
                   )}
                </tbody>
             </table>
        </div>
      </div>

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionStatus, UserKYC, Language } from './types';
import { BASE_RATE, SPREAD_PERCENT, PROMPTPAY_ID, THEME, TRANSLATIONS, RATE_REFRESH_MS, RATE_FLUCTUATION_RANGE } from './constants';
import { generatePromptPayPayload } from './utils/promptpay';
import { generateReferenceId, maskPII } from './utils/security';
import { MockBackend } from './services/mockBackend';
import { TransactionPulse } from './components/TransactionPulse';
import { AdminDashboard } from './components/AdminDashboard';
import QRCode from 'react-qr-code';
import { ArrowRight, Lock, User, Wallet, RefreshCw, Globe, TrendingUp } from 'lucide-react';

function App() {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [screen, setScreen] = useState<'SWAP' | 'KYC' | 'PULSE'>('SWAP');

  // Swap State
  const [amountTHB, setAmountTHB] = useState<number>(1000);
  const [rate, setRate] = useState<number>(BASE_RATE * (1 + SPREAD_PERCENT));

  // KYC State
  const [kycData, setKycData] = useState<UserKYC>({
    fullName: 'John Doe',
    nationalId: '1100012345678',
    walletAddress: 'T9yD14Nj9j7xAB4dbGeiX9h8unc5xh87f', // Sample TRC20
    isVerified: false
  });

  // Transaction State
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);

  // Poll for backend updates if in PULSE mode
  useEffect(() => {
    if (screen === 'PULSE') {
      const unsubscribe = MockBackend.subscribe((updatedTx) => {
        setActiveTx(updatedTx);
      });
      return unsubscribe;
    }
  }, [screen]);

  // Simulate Rate Fluctuation
  useEffect(() => {
    // Only fluctuate rates on the Swap screen. 
    // Once in KYC or Pulse, rate must be locked to prevent slippage.
    if (screen !== 'SWAP') return;

    const interval = setInterval(() => {
      // Create random fluctuation between -RANGE/2 and +RANGE/2
      const noise = (Math.random() - 0.5) * RATE_FLUCTUATION_RANGE;
      const newBase = BASE_RATE + noise;
      const finalRate = newBase * (1 + SPREAD_PERCENT);

      setRate(Number(finalRate.toFixed(2)));
    }, RATE_REFRESH_MS);

    return () => clearInterval(interval);
  }, [screen]);

  const handleSwapInit = () => {
    setScreen('KYC');
  };

  const handleKYCSubmit = () => {
    try {
      const amountUSDT = amountTHB / rate;
      const refId = generateReferenceId();

      // Generate PromptPay Payload
      // In production, QR generation might happen on backend to sign it, 
      // but standard allows client gen if parameters are correct.
      const qrPayload = generatePromptPayPayload(PROMPTPAY_ID, amountTHB);

      const newTx: Transaction = {
        id: Math.random().toString(36),
        referenceId: refId,
        user: { ...kycData, isVerified: true },
        amountTHB,
        amountUSDT: parseFloat(amountUSDT.toFixed(2)),
        rate,
        status: TransactionStatus.AWAITING_PAYMENT,
        timestamp: Date.now(),
        qrPayload,
        logs: []
      };

      MockBackend.createTransaction(newTx);
      setActiveTx(newTx);
      setScreen('PULSE');
    } catch (error) {
      console.error("Failed to generate transaction:", error);
      alert(t.errorGen);
    }
  };

  const toggleLang = () => {
    setLang(current => current === 'en' ? 'th' : 'en');
  };

  return (
    <div className={`min-h-screen ${THEME.bg} text-slate-200 p-4 md:p-8 font-sans selection:bg-emerald-500/30`}>

      {/* Header */}
      <header className="max-w-6xl mx-auto flex justify-between items-center mb-12">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setScreen('SWAP')}>
          <div className="w-10 h-10 bg-gradient-to-tr from-emerald-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-emerald-500/20">
             <span className="font-bold text-white text-xl">P</span>
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">PromptPay<span className="text-emerald-400">Crypto</span></h1>
            <p className="text-xs text-slate-400">{t.subtitle}</p>
          </div>
        </div>
        <div className="flex items-center gap-6">
            {/* Language Switcher */}
            <button 
                onClick={toggleLang}
                className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg border border-slate-700 transition-colors"
            >
                <Globe size={16} className="text-slate-400" />
                <span className="text-xs font-bold text-slate-200">{lang === 'en' ? 'EN' : 'TH'}</span>
            </button>
            <div className="hidden md:flex items-center gap-6 text-sm font-medium text-slate-400">
                <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-emerald-500"></span> {t.systemOp}</span>
                <span className="flex items-center gap-1 hover:text-white cursor-pointer"><Lock size={14} /> {t.securityCenter}</span>
            </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto space-y-12">

        {/* Screen 1: Swap Interface */}
        {screen === 'SWAP' && (
          <div className="max-w-md mx-auto">
            <div className={`${THEME.card} p-8 neon-border relative`}>
               <h2 className="text-2xl font-bold text-white mb-6">{t.buyTitle}</h2>

               <div className="space-y-6">
                 <div>
                    <label className="block text-xs font-medium text-slate-400 mb-2 uppercase tracking-wide">{t.youPay}</label>
                    <div className="relative">
                      <input 
                        type="number" 
                        value={amountTHB}
                        onChange={(e) => setAmountTHB(Number(e.target.value))}
                        className="w-full bg-slate-950 border border-slate-700 rounded-lg py-4 px-4 text-2xl font-mono text-white focus:outline-none focus:border-emerald-500 transition-colors"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">THB</span>
                    </div>
                 </div>

                 <div className="flex justify-center">
                    <div className="bg-slate-800 p-2 rounded-full border border-slate-700">
                      <ArrowRight className="text-slate-400 rotate-90" size={20} />
                    </div>
                 </div>

                 <div>
                    <label className="block text-xs font-medium text-slate-400 mb-2 uppercase tracking-wide">{t.youReceive}</label>
                    <div className="relative">
                      <input 
                        type="text" 
                        readOnly
                        value={(amountTHB / rate).toFixed(2)}
                        className="w-full bg-slate-900/50 border border-slate-700 rounded-lg py-4 px-4 text-2xl font-mono text-emerald-400 focus:outline-none"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-600 font-bold">USDT</span>
                    </div>
                 </div>

                 <div className="flex justify-between items-center text-xs text-slate-500 px-1">
                    <span className="flex items-center gap-1">
                        {t.rate}: 1 USDT = {rate.toFixed(2)} THB
                        <TrendingUp size={12} className="text-emerald-500" />
                    </span>
                    <span>{t.fees} (0.8%)</span>
                 </div>

                 <button 
                   onClick={handleSwapInit}
                   className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold py-4 rounded-lg shadow-[0_0_20px_rgba(16,185,129,0.3)] transition-all transform active:scale-95 flex justify-center items-center gap-2"
                 >
                   {t.proceed} <ArrowRight size={20} />
                 </button>
               </div>
            </div>
          </div>
        )}

        {/* Screen 2: KYC & Details */}
        {screen === 'KYC' && (
           <div className="max-w-md mx-auto">
             <div className={`${THEME.card} p-8 border-t border-indigo-500`}>
                <div className="flex items-center gap-2 mb-6 text-indigo-400">
                   <User size={24} />
                   <h2 className="text-xl font-bold text-white">{t.kycTitle}</h2>
                </div>
                <p className="text-slate-400 text-sm mb-6">
                  {t.kycDesc}
                </p>

                <div className="space-y-4 mb-8">
                  <div>
                    <label className="text-xs text-slate-500 block mb-1">{t.fullName}</label>
                    <input 
                      type="text" 
                      value={kycData.fullName}
                      onChange={(e) => setKycData({...kycData, fullName: e.target.value})}
                      className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-indigo-500 outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-slate-500 block mb-1">{t.nationalId}</label>
                    <input 
                      type="text" 
                      value={kycData.nationalId}
                      onChange={(e) => setKycData({...kycData, nationalId: e.target.value})}
                      className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-indigo-500 outline-none"
                    />
                  </div>
                   <div>
                    <label className="text-xs text-slate-500 block mb-1">{t.wallet}</label>
                    <input 
                      type="text" 
                      value={kycData.walletAddress}
                      onChange={(e) => setKycData({...kycData, walletAddress: e.target.value})}
                      className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-mono text-xs text-indigo-300 focus:border-indigo-500 outline-none"
                    />
                  </div>
                </div>

                <div className="flex gap-4">
                  <button 
                    onClick={() => setScreen('SWAP')}
                    className="flex-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold py-3 rounded-lg transition-colors"
                  >
                    {t.back}
                  </button>
                  <button 
                     onClick={handleKYCSubmit}
                     className="flex-[2] bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3 rounded-lg transition-colors"
                   >
                     {t.confirm}
                   </button>
                </div>
             </div>
           </div>
        )}

        {/* Screen 3: Pulse & QR */}
        {screen === 'PULSE' && activeTx && (
          <div className="space-y-8 animate-fade-in">
             <TransactionPulse transaction={activeTx} lang={lang} />

             {activeTx.status === TransactionStatus.AWAITING_PAYMENT && (
               <div className="max-w-2xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className={`p-6 ${THEME.card} flex flex-col items-center justify-center text-center`}>
                      <div className="bg-white p-4 rounded-lg shadow-xl mb-4">
                         <QRCode value={activeTx.qrPayload || ''} size={180} />
                      </div>
                      <p className="text-emerald-400 font-bold text-lg mb-1">{t.scan}</p>
                      <p className="text-slate-500 text-xs">{t.scanDesc}</p>
