        <AdminDashboard lang={lang} />

      </main>

      <footer className="max-w-6xl mx-auto mt-20 pt-8 border-t border-slate-800 text-center text-slate-600 text-xs">
        <p>© 2024 PromptPay Crypto Gateway Prototype. All rights reserved.</p>
        <p className="mt-2 font-mono">Build: v0.9.3-BETA | Environment: Sandbox</p>
