export default App;

export enum TransactionStatus {
  IDLE = 'IDLE',
  KYC_PENDING = 'KYC_PENDING',
  AWAITING_PAYMENT = 'AWAITING_PAYMENT',
  VERIFYING_BANK = 'VERIFYING_BANK', // Logic Guard
  DISBURSING = 'DISBURSING', // Crypto Transfer
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export type Language = 'en' | 'th';

export interface UserKYC {
  fullName: string;
  nationalId: string; // Thai ID or Passport
  walletAddress: string;
  isVerified: boolean;
}

export interface Transaction {
  id: string;
  referenceId: string; // For bank reconciliation
  user: UserKYC;
  amountTHB: number;
  amountUSDT: number;
  rate: number;
  status: TransactionStatus;
  timestamp: number;
  qrPayload?: string;
  logs: LogEntry[];
}

export interface LogEntry {
  timestamp: string;
  level: 'INFO' | 'WARN' | 'CRITICAL';
  module: 'WEBHOOK' | 'KYC' | 'LEDGER' | 'DISBURSER';
  message: string;
  hash: string; // Simulated hash of the log for integrity
}

export interface OrderBook {
  thbReserves: number;
  usdtReserves: number;
  autoHedge: boolean;
  spread: number;
}

export interface AppConfig {
  baseRate: number;
  feePercent: number; // Stored as percentage (e.g. 0.8 for 0.8%)
  promptPayId: string;
  providerWallet: string;
}

import { BASE_RATE, SPREAD_PERCENT, PROMPTPAY_ID } from '../constants';
import { AppConfig } from '../types';

// Default initial configuration derived from constants
let currentConfig: AppConfig = {
  baseRate: BASE_RATE,
  feePercent: SPREAD_PERCENT * 100, // Convert 0.008 to 0.8 for display/editing
  promptPayId: PROMPTPAY_ID,
  providerWallet: "TWd4...SimulatedProviderHotWallet" 
};

let listeners: ((config: AppConfig) => void)[] = [];

export const ConfigService = {
  // Get current snapshot
  get: () => ({ ...currentConfig }),

  // Update specific fields and notify listeners
  update: (updates: Partial<AppConfig>) => {
    currentConfig = { ...currentConfig, ...updates };
    listeners.forEach(l => l(currentConfig));
  },

  // Subscribe to changes
  subscribe: (callback: (config: AppConfig) => void) => {
    listeners.push(callback);
    callback(currentConfig); // Fire immediately with current state
    return () => {
      listeners = listeners.filter(l => l !== callback);
    };
  }
};

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionStatus, UserKYC, Language, AppConfig } from './types';
import { THEME, TRANSLATIONS, RATE_REFRESH_MS, RATE_FLUCTUATION_RANGE } from './constants';
import { generatePromptPayPayload } from './utils/promptpay';
import { generateReferenceId, maskPII } from './utils/security';
import { MockBackend } from './services/mockBackend';
import { ConfigService } from './services/configService';
import { TransactionPulse } from './components/TransactionPulse';
import { AdminDashboard } from './components/AdminDashboard';
