function App() {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [screen, setScreen] = useState<'SWAP' | 'KYC' | 'PULSE'>('SWAP');

  // Configuration State
  const [config, setConfig] = useState<AppConfig>(ConfigService.get());

  // Swap State
  const [amountTHB, setAmountTHB] = useState<number>(1000);
  // Rate state includes fluctuation
  const [displayRate, setDisplayRate] = useState<number>(config.baseRate * (1 + config.feePercent / 100));

  // KYC State
  const [kycData, setKycData] = useState<UserKYC>({
    fullName: 'John Doe',
    nationalId: '1100012345678',
    walletAddress: 'T9yD14Nj9j7xAB4dbGeiX9h8unc5xh87f', // Sample TRC20
    isVerified: false
  });

  // Transaction State
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);

  // Subscribe to Global Config Changes
  useEffect(() => {
    const unsubscribe = ConfigService.subscribe((newConfig) => {
      setConfig(newConfig);
      // Immediately update display rate when config changes base/fee
      const newRate = newConfig.baseRate * (1 + newConfig.feePercent / 100);
      setDisplayRate(Number(newRate.toFixed(2)));
    });
    return unsubscribe;
  }, []);

  // Poll for backend updates if in PULSE mode
  useEffect(() => {
    if (screen === 'PULSE') {
      const unsubscribe = MockBackend.subscribe((updatedTx) => {
        setActiveTx(updatedTx);
      });
      return unsubscribe;
    }
  }, [screen]);

  // Simulate Rate Fluctuation
  useEffect(() => {
    // Only fluctuate rates on the Swap screen. 
    // Once in KYC or Pulse, rate must be locked to prevent slippage.
    if (screen !== 'SWAP') return;

    const interval = setInterval(() => {
      // Create random fluctuation between -RANGE/2 and +RANGE/2
      const noise = (Math.random() - 0.5) * RATE_FLUCTUATION_RANGE;
      const newBase = config.baseRate + noise;
      const finalRate = newBase * (1 + config.feePercent / 100);

      setDisplayRate(Number(finalRate.toFixed(2)));
    }, RATE_REFRESH_MS);

    return () => clearInterval(interval);
  }, [screen, config.baseRate, config.feePercent]);

  const handleSwapInit = () => {
    setScreen('KYC');
  };

  const handleKYCSubmit = () => {
    try {
      const amountUSDT = amountTHB / displayRate;
      const refId = generateReferenceId();

      // Generate PromptPay Payload using Configured ID
      const qrPayload = generatePromptPayPayload(config.promptPayId, amountTHB);

      const newTx: Transaction = {
        id: Math.random().toString(36),
        referenceId: refId,
        user: { ...kycData, isVerified: true },
        amountTHB,
        amountUSDT: parseFloat(amountUSDT.toFixed(2)),
        rate: displayRate,
        status: TransactionStatus.AWAITING_PAYMENT,
        timestamp: Date.now(),
        qrPayload,
        logs: []
      };

      MockBackend.createTransaction(newTx);
      setActiveTx(newTx);
      setScreen('PULSE');
    } catch (error) {
      console.error("Failed to generate transaction:", error);
      alert(t.errorGen);
    }
  };

  const toggleLang = () => {
    setLang(current => current === 'en' ? 'th' : 'en');
