import React from 'react';
import { Transaction, TransactionStatus, Language } from '../types';
import { Check, Loader2, ShieldCheck, Wallet, ArrowLeftRight, Server, AlertTriangle, X } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

interface Props {
  transaction: Transaction;
  lang: Language;
}

export const TransactionPulse: React.FC<Props> = ({ transaction, lang }) => {
  const t = TRANSLATIONS[lang];
  const isFailed = transaction.status === TransactionStatus.FAILED;

  const steps = [
    { id: TransactionStatus.AWAITING_PAYMENT, label: t.stepPayment, icon: ArrowLeftRight },
    { id: TransactionStatus.VERIFYING_BANK, label: t.stepBank, icon: Server },
    { id: TransactionStatus.DISBURSING, label: t.stepDisburse, icon: Wallet },
    { id: TransactionStatus.COMPLETED, label: t.stepComplete, icon: Check },
  ];

  // Determine current active step index
  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      case TransactionStatus.FAILED: return 1; 
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  // Extract failure reason from logs if failed
  const failureReason = isFailed 
    ? (transaction.logs.find(l => l.level === 'CRITICAL')?.message || 'Compliance checks failed.') 
    : null;

  return (
    <div className={`w-full max-w-2xl mx-auto ${THEME.card} overflow-hidden`}>
      {/* Header */}
      <div className="bg-slate-900/50 p-4 border-b border-slate-800 flex justify-between items-center">
         <div>
            <h2 className={`text-sm font-bold uppercase tracking-wide ${isFailed ? 'text-red-500' : 'text-white'}`}>
              {isFailed ? t.txFailed : t.txPulse}
            </h2>
            <span className="text-[10px] text-slate-500 font-mono">REF: {transaction.referenceId}</span>
         </div>
         <div className={`px-2 py-1 rounded text-[10px] font-bold border ${isFailed ? 'bg-red-950/30 text-red-500 border-red-900/50' : 'bg-emerald-950/30 text-emerald-500 border-emerald-900/50'}`}>
             {isFailed ? t.rejected : t.secure}
         </div>
      </div>

      <div className="p-6">
        {/* Progress Tracker */}
        <div className="flex items-center justify-between relative mb-8 px-4">
          {/* Background Line */}
          <div className="absolute top-4 left-4 right-4 h-0.5 bg-slate-800 -z-10"></div>

          {/* Active Line (Visual approximation) */}
          <div 
            className={`absolute top-4 left-4 h-0.5 ${isFailed ? 'bg-red-500/50' : 'bg-emerald-500'} transition-all duration-700 -z-10`}
            style={{ width: `calc(${ (currentStep / (steps.length - 1)) * 100 }% - 2rem)` }}
          ></div>

          {steps.map((step, index) => {
            const isActive = index === currentStep;
            const isCompleted = index < currentStep;
            const Icon = step.icon;

            let circleClass = 'bg-slate-900 border-slate-700 text-slate-600';
            if (isActive) {
               if (isFailed) {
                   circleClass = 'bg-red-900 border-red-500 text-white';
               } else {
                   circleClass = 'bg-emerald-600 border-emerald-500 text-white ring-4 ring-emerald-500/10';
               }
            } else if (isCompleted) {
               circleClass = 'bg-emerald-900 border-emerald-700 text-emerald-400';
            }

            return (
              <div key={step.id} className="flex flex-col items-center gap-2">
                <div 
                  className={`w-8 h-8 rounded-full flex items-center justify-center border text-xs transition-all duration-500 ${circleClass}`}
                >
                  {isActive && !isFailed && step.id !== TransactionStatus.COMPLETED ? (
                      <Loader2 size={14} className="animate-spin" />
                  ) : (
                      <Icon size={14} />
                  )}
                </div>
                <span className={`text-[10px] font-medium uppercase tracking-wider ${isActive ? (isFailed ? 'text-red-400' : 'text-white') : 'text-slate-600'}`}>
                  {step.label}
                </span>
              </div>
            );
          })}
        </div>

        {/* Info Grid */}
        <div className="grid grid-cols-2 gap-4 bg-slate-950 rounded border border-slate-800 p-4">
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.status}</p>
              <p className={`text-xs font-mono font-bold ${isFailed ? 'text-red-500' : 'text-emerald-400'}`}>
                {transaction.status.replace(/_/g, ' ')}
              </p>
           </div>
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.incoming}</p>
              <p className="text-xs font-mono text-white">฿ {transaction.amountTHB.toLocaleString()}</p>
           </div>
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.outgoing}</p>
              <p className="text-xs font-mono text-white">₮ {transaction.amountUSDT.toLocaleString()}</p>
           </div>
           <div>
               <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.rate}</p>
               <p className="text-xs font-mono text-slate-400">{transaction.rate.toFixed(2)}</p>
           </div>
        </div>

        {/* Dynamic Status Banner */}
        {transaction.status === TransactionStatus.VERIFYING_BANK && !isFailed && (
            <div className="mt-4 flex items-center gap-2 text-xs text-indigo-400 bg-indigo-900/10 p-2 rounded border border-indigo-900/30">
                <Loader2 size={14} className="animate-spin" />
                <span>{t.verifying}</span>
            </div>
        )}
         {transaction.status === TransactionStatus.DISBURSING && !isFailed && (
            <div className="mt-4 flex items-center gap-2 text-xs text-emerald-400 bg-emerald-900/10 p-2 rounded border border-emerald-900/30">
                <Wallet size={14} />
                <span>{t.initiating}</span>
            </div>
        )}
        {isFailed && (
            <div className="mt-4 flex items-start gap-2 text-xs text-red-400 bg-red-900/10 p-2 rounded border border-red-900/30">
                <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                <div>
                   <p className="font-bold mb-0.5">{t.alert}</p>
                   <p className="opacity-80">{failureReason}</p>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Transaction, LogEntry, TransactionStatus, Language, AppConfig } from '../types';
import { MockBackend } from '../services/mockBackend';
import { ConfigService } from '../services/configService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { Shield, RefreshCw, Terminal, History, Zap, AlertCircle, Settings, Save, Server } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

const data = [
  { name: '08:00', thb: 400000, usdt: 12000 },
  { name: '10:00', thb: 600000, usdt: 10000 },
  { name: '12:00', thb: 300000, usdt: 18000 },
  { name: '14:00', thb: 800000, usdt: 8000 },
  { name: '16:00', thb: 950000, usdt: 5000 },
];

interface Props {
  lang: Language;
}

export const AdminDashboard: React.FC<Props> = ({ lang }) => {
  const t = TRANSLATIONS[lang];
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [reserves, setReserves] = useState(MockBackend.getOrderBook());
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);
  const [history, setHistory] = useState<Transaction[]>([]);

  // Simulation inputs
  const [simName, setSimName] = useState('John Doe');
  const [simAmount, setSimAmount] = useState(1000);
  const [simError, setSimError] = useState<string | null>(null);

  // Global Config inputs
  const [config, setConfig] = useState<AppConfig>(ConfigService.get());
  const [editConfig, setEditConfig] = useState<AppConfig>(ConfigService.get());
  const [isConfigChanged, setIsConfigChanged] = useState(false);

  useEffect(() => {
    // Sync with backend simulation
    const interval = setInterval(() => {
      setLogs([...MockBackend.getLogs()]);
      setReserves({...MockBackend.getOrderBook()});
      setActiveTx(MockBackend.getCurrentTransaction());
      setHistory([...MockBackend.getTransactionHistory()]);

      const current = MockBackend.getCurrentTransaction();
      if (current) {
         if (simName === 'John Doe' && simAmount === 1000) {
            setSimName(current.user.fullName || 'John Doe');
            setSimAmount(current.amountTHB || 1000);
         }
      }
    }, 1000);

    const unsubscribeConfig = ConfigService.subscribe((newConfig) => {
        setConfig(newConfig);
    });

    return () => {
        clearInterval(interval);
        unsubscribeConfig();
    };
  }, [simName, simAmount]);

  const triggerWebhook = () => {
    setSimError(null);
    if (!activeTx) { setSimError(t.errNoTx); return; }
    if (!simName || simName.trim().length === 0) { setSimError(t.errSenderName); return; }
    if (simAmount <= 0 || isNaN(simAmount)) { setSimError(t.errAmount); return; }
    MockBackend.triggerIncomingTransfer(simAmount, simName, activeTx.referenceId);
  };

  const toggleHedge = () => {
    MockBackend.toggleAutoHedge();
    setReserves({...MockBackend.getOrderBook()});
  };

  const handleConfigChange = (key: keyof AppConfig, value: string | number) => {
    setEditConfig(prev => ({...prev, [key]: value}));
    setIsConfigChanged(true);
  };

  const saveConfig = () => {
    ConfigService.update(editConfig);
    setIsConfigChanged(false);
  };

  const completedHistory = history.filter(tx => 
    tx.status === TransactionStatus.COMPLETED || tx.status === TransactionStatus.FAILED
  );

  return (
    <div className={`mt-12 ${THEME.card} overflow-hidden`}>
      {/* Admin Header */}
      <div className="bg-slate-900 p-4 border-b border-slate-800 flex items-center justify-between">
         <div className="flex items-center gap-2">
            <Server size={18} className="text-slate-400" />
            <h3 className="text-sm font-bold text-slate-200">{t.adminConsole}</h3>
         </div>
         <span className="text-[10px] font-mono text-emerald-500 bg-emerald-950/30 px-2 py-0.5 rounded border border-emerald-900/50">{t.secAudit}</span>
      </div>

      <div className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Metrics & Controls */}
        <div className="lg:col-span-2 space-y-6">

            {/* Metric Cards */}
            <div className="grid grid-cols-3 gap-4">
                <div className="bg-slate-950 border border-slate-800 p-3 rounded">
                    <p className="text-[10px] text-slate-500 uppercase">{t.thbReserves}</p>
                    <p className="text-lg font-mono text-emerald-400">฿{reserves.thbReserves.toLocaleString()}</p>
                </div>
                <div className="bg-slate-950 border border-slate-800 p-3 rounded">
                    <p className="text-[10px] text-slate-500 uppercase">{t.usdtFloat}</p>
                    <p className="text-lg font-mono text-indigo-400">₮{reserves.usdtReserves.toLocaleString()}</p>
                </div>
                 <div className="bg-slate-950 border border-slate-800 p-3 rounded flex flex-col justify-center">
                    <div className="flex items-center justify-between">
                         <span className="text-[10px] text-slate-500 uppercase">{t.autoHedge}</span>
                         <div className={`w-2 h-2 rounded-full ${reserves.autoHedge ? 'bg-emerald-500' : 'bg-slate-600'}`}></div>
                    </div>
                    <button 
                        onClick={toggleHedge} 
                        className="mt-1 text-[10px] bg-slate-800 hover:bg-slate-700 text-slate-300 py-1 px-2 rounded border border-slate-700 w-full"
                    >
                        Toggle Status
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                {/* Configuration Panel */}
                <div className="border border-slate-800 rounded bg-slate-900/50">
                     <div className="p-3 border-b border-slate-800 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-300 flex items-center gap-2">
                           <Settings size={12} /> {t.globalSettings}
                        </span>
                        {isConfigChanged && (
                            <button onClick={saveConfig} className="text-[10px] bg-emerald-700 text-white px-2 py-0.5 rounded flex items-center gap-1">
                                <Save size={10} /> {t.save}
                            </button>
                        )}
                     </div>
                     <div className="p-3 space-y-2">
                         <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="text-[9px] text-slate-500 uppercase block mb-1">{t.lblBaseRate}</label>
                                <input type="number" step="0.01" value={editConfig.baseRate} onChange={(e) => handleConfigChange('baseRate', parseFloat(e.target.value))} className={THEME.input + " h-8 text-xs"} />
                            </div>
                            <div>
                                <label className="text-[9px] text-slate-500 uppercase block mb-1">{t.lblServiceFee}</label>
                                <input type="number" step="0.1" value={editConfig.feePercent} onChange={(e) => handleConfigChange('feePercent', parseFloat(e.target.value))} className={THEME.input + " h-8 text-xs"} />
                            </div>
                         </div>
                         <div>
                            <label className="text-[9px] text-slate-500 uppercase block mb-1">{t.lblMerchantId}</label>
                            <input type="text" value={editConfig.promptPayId} onChange={(e) => handleConfigChange('promptPayId', e.target.value)} className={THEME.input + " h-8 text-xs font-mono"} />
                         </div>
                     </div>
                </div>

                {/* Chart */}
                <div className="border border-slate-800 rounded bg-slate-900/50 p-2 h-[180px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data}>
                            <XAxis dataKey="name" stroke="#475569" fontSize={9} />
                            <YAxis stroke="#475569" fontSize={9} />
                            <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', fontSize: '10px' }} />
                            <Bar dataKey="thb" fill="#10b981" />
                            <Bar dataKey="usdt" fill="#6366f1" />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            {/* Webhook Tool */}
            <div className="border border-slate-800 rounded p-3 bg-slate-950">
                <p className="text-[10px] text-slate-500 uppercase font-bold mb-2 flex items-center gap-1">
                    <RefreshCw size={10} /> {t.webhookSim}
                </p>
                <div className="flex gap-2">
                    <input type="text" value={simName} onChange={(e) => setSimName(e.target.value)} className={THEME.input + " h-8 text-xs"} placeholder={t.senderNamePlaceholder} />
                    <input type="number" value={simAmount} onChange={(e) => setSimAmount(Number(e.target.value))} className={THEME.input + " h-8 text-xs w-24"} placeholder={t.amountPlaceholder} />
                    <button onClick={triggerWebhook} className="bg-indigo-600 hover:bg-indigo-500 text-white px-3 py-1 rounded text-xs h-8 whitespace-nowrap">
                        {t.triggerWebhook}
                    </button>
                </div>
                {simError && <p className="text-[10px] text-red-500 mt-1">{simError}</p>}
            </div>
        </div>

