import React from 'react';
import { Transaction, TransactionStatus, Language } from '../types';
import { Check, Loader2, ShieldCheck, Wallet, ArrowLeftRight, Server, AlertTriangle, X } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

interface Props {
  transaction: Transaction;
  lang: Language;
}

export const TransactionPulse: React.FC<Props> = ({ transaction, lang }) => {
  const t = TRANSLATIONS[lang];
  const isFailed = transaction.status === TransactionStatus.FAILED;

  const steps = [
    { id: TransactionStatus.AWAITING_PAYMENT, label: t.stepPayment, icon: ArrowLeftRight },
    { id: TransactionStatus.VERIFYING_BANK, label: t.stepBank, icon: Server },
    { id: TransactionStatus.DISBURSING, label: t.stepDisburse, icon: Wallet },
    { id: TransactionStatus.COMPLETED, label: t.stepComplete, icon: Check },
  ];

  // Determine current active step index
  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      case TransactionStatus.FAILED: return 1; 
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  // Extract failure reason from logs if failed
  const failureReason = isFailed 
    ? (transaction.logs.find(l => l.level === 'CRITICAL')?.message || 'Compliance checks failed.') 
    : null;

  return (
    <div className={`w-full max-w-2xl mx-auto ${THEME.card} overflow-hidden`}>
      {/* Header */}
      <div className="bg-slate-50 p-4 border-b border-slate-200 flex justify-between items-center">
         <div>
            <h2 className={`text-sm font-bold uppercase tracking-wide ${isFailed ? 'text-red-600' : 'text-slate-800'}`}>
              {isFailed ? t.txFailed : t.txPulse}
            </h2>
            <span className="text-[10px] text-slate-500 font-mono">REF: {transaction.referenceId}</span>
         </div>
         <div className={`px-2 py-1 rounded text-[10px] font-bold border ${isFailed ? 'bg-red-50 text-red-600 border-red-200' : 'bg-green-50 text-green-700 border-green-200'}`}>
             {isFailed ? t.rejected : t.secure}
         </div>
      </div>

      <div className="p-6">
        {/* Progress Tracker */}
        <div className="flex items-center justify-between relative mb-8 px-4">
          {/* Background Line */}
          <div className="absolute top-4 left-4 right-4 h-0.5 bg-slate-200 -z-10"></div>

          {/* Active Line (Visual approximation) */}
          <div 
            className={`absolute top-4 left-4 h-0.5 ${isFailed ? 'bg-red-500' : 'bg-blue-600'} transition-all duration-700 -z-10`}
            style={{ width: `calc(${ (currentStep / (steps.length - 1)) * 100 }% - 2rem)` }}
          ></div>

          {steps.map((step, index) => {
            const isActive = index === currentStep;
            const isCompleted = index < currentStep;
            const Icon = step.icon;

            let circleClass = 'bg-white border-slate-300 text-slate-400';
            if (isActive) {
               if (isFailed) {
                   circleClass = 'bg-red-50 border-red-500 text-red-600';
               } else {
                   circleClass = 'bg-white border-blue-600 text-blue-600 ring-4 ring-blue-50';
               }
            } else if (isCompleted) {
               circleClass = 'bg-blue-600 border-blue-600 text-white';
            }

            return (
              <div key={step.id} className="flex flex-col items-center gap-2">
                <div 
                  className={`w-8 h-8 rounded-full flex items-center justify-center border text-xs transition-all duration-500 ${circleClass}`}
                >
                  {isActive && !isFailed && step.id !== TransactionStatus.COMPLETED ? (
                      <Loader2 size={14} className="animate-spin" />
                  ) : (
                      <Icon size={14} />
                  )}
                </div>
                <span className={`text-[10px] font-bold uppercase tracking-wider ${isActive ? (isFailed ? 'text-red-600' : 'text-blue-700') : 'text-slate-400'}`}>
                  {step.label}
                </span>
              </div>
            );
          })}
        </div>

        {/* Info Grid */}
        <div className="grid grid-cols-2 gap-4 bg-slate-50 rounded border border-slate-200 p-4">
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.status}</p>
              <p className={`text-xs font-mono font-bold ${isFailed ? 'text-red-600' : 'text-blue-700'}`}>
                {transaction.status.replace(/_/g, ' ')}
              </p>
           </div>
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.incoming}</p>
              <p className="text-xs font-mono text-slate-800">฿ {transaction.amountTHB.toLocaleString()}</p>
           </div>
           <div>
              <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.outgoing}</p>
              <p className="text-xs font-mono text-slate-800">₮ {transaction.amountUSDT.toLocaleString()}</p>
           </div>
           <div>
               <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">{t.rate}</p>
               <p className="text-xs font-mono text-slate-500">{transaction.rate.toFixed(2)}</p>
           </div>
        </div>

        {/* Dynamic Status Banner */}
        {transaction.status === TransactionStatus.VERIFYING_BANK && !isFailed && (
            <div className="mt-4 flex items-center gap-2 text-xs text-blue-700 bg-blue-50 p-3 rounded border border-blue-100">
                <Loader2 size={14} className="animate-spin" />
                <span className="font-medium">{t.verifying}</span>
            </div>
        )}
         {transaction.status === TransactionStatus.DISBURSING && !isFailed && (
            <div className="mt-4 flex items-center gap-2 text-xs text-green-700 bg-green-50 p-3 rounded border border-green-100">
                <Wallet size={14} />
                <span className="font-medium">{t.initiating}</span>
            </div>
        )}
        {isFailed && (
            <div className="mt-4 flex items-start gap-2 text-xs text-red-700 bg-red-50 p-3 rounded border border-red-100">
                <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                <div>
                   <p className="font-bold mb-0.5">{t.alert}</p>
                   <p className="opacity-80">{failureReason}</p>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

