                   <p className="text-red-600">{failureReason}</p>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionStatus, UserKYC, Language, AppConfig } from './types';
import { THEME, TRANSLATIONS, RATE_REFRESH_MS, RATE_FLUCTUATION_RANGE } from './constants';
import { generatePromptPayPayload } from './utils/promptpay';
import { generateReferenceId, maskPII } from './utils/security';
import { MockBackend } from './services/mockBackend';
import { ConfigService } from './services/configService';
import { TransactionPulse } from './components/TransactionPulse';
import { AdminDashboard } from './components/AdminDashboard';
import QRCode from 'react-qr-code';
import { ArrowRight, Lock, User, Wallet, RefreshCw, Globe, TrendingUp, ShieldCheck, Building2, ChevronRight, HelpCircle } from 'lucide-react';

function App() {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [screen, setScreen] = useState<'SWAP' | 'KYC' | 'PULSE'>('SWAP');

  // Configuration State
  const [config, setConfig] = useState<AppConfig>(ConfigService.get());

  // Swap State
  const [amountTHB, setAmountTHB] = useState<number>(1000);
  // Rate state includes fluctuation
  const [displayRate, setDisplayRate] = useState<number>(config.baseRate * (1 + config.feePercent / 100));

  // KYC State
  const [kycData, setKycData] = useState<UserKYC>({
    fullName: 'John Doe',
    nationalId: '1100012345678',
    walletAddress: 'T9yD14Nj9j7xAB4dbGeiX9h8unc5xh87f', // Sample TRC20
    isVerified: false
  });

  // Transaction State
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);

  // Subscribe to Global Config Changes
  useEffect(() => {
    const unsubscribe = ConfigService.subscribe((newConfig) => {
      setConfig(newConfig);
      // Immediately update display rate when config changes base/fee
      const newRate = newConfig.baseRate * (1 + newConfig.feePercent / 100);
      setDisplayRate(Number(newRate.toFixed(2)));
    });
    return unsubscribe;
  }, []);

  // Poll for backend updates if in PULSE mode
  useEffect(() => {
    if (screen === 'PULSE') {
      const unsubscribe = MockBackend.subscribe((updatedTx) => {
        setActiveTx(updatedTx);
      });
      return unsubscribe;
    }
  }, [screen]);

  // Simulate Rate Fluctuation
  useEffect(() => {
    // Only fluctuate rates on the Swap screen. 
    // Once in KYC or Pulse, rate must be locked to prevent slippage.
    if (screen !== 'SWAP') return;

    const interval = setInterval(() => {
      // Create random fluctuation between -RANGE/2 and +RANGE/2
      const noise = (Math.random() - 0.5) * RATE_FLUCTUATION_RANGE;
      const newBase = config.baseRate + noise;
      const finalRate = newBase * (1 + config.feePercent / 100);

      setDisplayRate(Number(finalRate.toFixed(2)));
    }, RATE_REFRESH_MS);

    return () => clearInterval(interval);
  }, [screen, config.baseRate, config.feePercent]);

  const handleSwapInit = () => {
    setScreen('KYC');
  };

  const handleKYCSubmit = () => {
    try {
      const amountUSDT = amountTHB / displayRate;
      const refId = generateReferenceId();

      // Generate PromptPay Payload using Configured ID
      const qrPayload = generatePromptPayPayload(config.promptPayId, amountTHB);

      const newTx: Transaction = {
        id: Math.random().toString(36),
        referenceId: refId,
        user: { ...kycData, isVerified: true },
        amountTHB,
        amountUSDT: parseFloat(amountUSDT.toFixed(2)),
        rate: displayRate,
        status: TransactionStatus.AWAITING_PAYMENT,
        timestamp: Date.now(),
        qrPayload,
        logs: []
      };

      MockBackend.createTransaction(newTx);
      setActiveTx(newTx);
      setScreen('PULSE');
    } catch (error) {
      console.error("Failed to generate transaction:", error);
      alert(t.errorGen);
    }
  };

  const toggleLang = () => {
    setLang(current => current === 'en' ? 'th' : 'en');
  };

  return (
    <div className={`min-h-screen ${THEME.bg} text-slate-600 font-sans selection:bg-blue-100 flex flex-col`}>

      {/* Formal Header with Top Bar */}
      <header className="sticky top-0 z-50 shadow-sm">
        {/* Top Utility Bar */}
        <div className="bg-slate-900 text-slate-300 text-[10px] py-1.5 px-6 hidden md:block border-b border-slate-800">
          <div className="max-w-5xl mx-auto flex justify-between items-center">
             <div className="flex gap-4">
               <span>Personal Banking</span>
               <span className="text-slate-500">|</span>
               <span>Business</span>
               <span className="text-slate-500">|</span>
               <span className="text-white font-semibold">Crypto Gateway</span>
             </div>
             <div className="flex gap-4 items-center">
               <span className="flex items-center gap-1.5 text-emerald-400"><span className="w-1.5 h-1.5 rounded-full bg-emerald-400"></span> {t.systemOp}</span>
               <span>Secure Connection</span>
             </div>
          </div>
        </div>

        {/* Main Nav Bar */}
        <div className="bg-white border-b border-slate-200">
          <div className="max-w-5xl mx-auto px-6 h-16 flex justify-between items-center">
            <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setScreen('SWAP')}>
              <div className="w-10 h-10 bg-blue-900 rounded-sm flex items-center justify-center text-white font-bold text-lg shadow-sm group-hover:bg-blue-800 transition-colors">
                 <Building2 size={20} />
              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold text-slate-900 tracking-wide uppercase">PromptPay<span className="text-blue-800">Direct</span></span>
                <span className="text-[10px] text-slate-500 font-medium">Digital Asset Remittance</span>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <div className="hidden md:flex gap-1">
                 <button className="px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-blue-800 hover:bg-slate-50 rounded transition-colors">Help Center</button>
                 <button className="px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-blue-800 hover:bg-slate-50 rounded transition-colors">Rates</button>
              </div>
               <div className="h-5 w-px bg-slate-200 hidden md:block"></div>
               <button 
                  onClick={toggleLang}
                  className="text-xs font-bold text-slate-600 hover:text-blue-900 transition-colors bg-slate-100 px-3 py-1.5 rounded-sm border border-slate-200 flex items-center gap-1"
              >
                  <Globe size={12} />
                  {lang === 'en' ? 'EN' : 'TH'}
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-5xl mx-auto w-full p-6 md:py-12 space-y-8">

        {/* Screen 1: Swap Interface (Bank Transfer Style) */}
        {screen === 'SWAP' && (
          <div className="max-w-xl mx-auto">
