                <p className="text-slate-500 text-sm">Securely transfer funds from your Thai bank account to digital assets.</p>
             </div>

            <div className={`${THEME.card} overflow-hidden shadow-md border-0`}>
               <div className="bg-slate-50 border-b border-slate-200 px-8 py-4 flex items-center gap-2">
