import React from 'react';
import { Transaction, TransactionStatus, Language } from '../types';
import { Check, Loader2, Wallet, ArrowLeftRight, Server, AlertTriangle, FileText } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

interface Props {
  transaction: Transaction;
  lang: Language;
}

export const TransactionPulse: React.FC<Props> = ({ transaction, lang }) => {
  const t = TRANSLATIONS[lang];
  const isFailed = transaction.status === TransactionStatus.FAILED;

  const steps = [
    { id: TransactionStatus.AWAITING_PAYMENT, label: t.stepPayment, icon: ArrowLeftRight },
    { id: TransactionStatus.VERIFYING_BANK, label: t.stepBank, icon: Server },
    { id: TransactionStatus.DISBURSING, label: t.stepDisburse, icon: Wallet },
    { id: TransactionStatus.COMPLETED, label: t.stepComplete, icon: Check },
  ];

  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      case TransactionStatus.FAILED: return 1; 
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  const failureReason = isFailed 
    ? (transaction.logs.find(l => l.level === 'CRITICAL')?.message || 'Compliance checks failed.') 
    : null;

  return (
    <div className={`w-full max-w-2xl mx-auto ${THEME.card} overflow-hidden shadow-sm`}>
      {/* Formal Header with Receipt styling */}
      <div className="bg-slate-50 dark:bg-slate-900 px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-slate-500 dark:text-slate-400">
               <FileText size={18} />
            </div>
            <div>
               <h2 className="text-sm font-bold text-slate-800 dark:text-slate-200 uppercase tracking-wide">
                 {isFailed ? t.txFailed : t.txPulse}
               </h2>
               <p className="text-[11px] text-slate-500 dark:text-slate-400 font-mono mt-0.5">REF: {transaction.referenceId}</p>
            </div>
         </div>
         <div className={`px-3 py-1 rounded-full text-[10px] font-bold border ${isFailed ? 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-400 border-red-200 dark:border-red-800' : 'bg-blue-50 dark:bg-blue-900/20 text-blue-800 dark:text-blue-300 border-blue-200 dark:border-blue-800'}`}>
             {isFailed ? t.rejected : t.secure}
         </div>
      </div>

      <div className="p-6 md:p-8 bg-white dark:bg-slate-950">
        {/* Formal Linear Progress Tracker */}
        <div className="mb-10 relative">
          <div className="absolute top-1/2 left-0 w-full h-1 bg-slate-100 dark:bg-slate-800 -translate-y-1/2 rounded-full -z-10"></div>
          <div 
            className={`absolute top-1/2 left-0 h-1 -translate-y-1/2 rounded-full transition-all duration-700 -z-10 ${isFailed ? 'bg-red-500' : 'bg-blue-800 dark:bg-blue-600'}`}
            style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }}
          ></div>

          <div className="flex justify-between w-full">
            {steps.map((step, index) => {
              const isActive = index === currentStep;
              const isCompleted = index < currentStep;
              const Icon = step.icon;

              let circleClass = 'bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-700 text-slate-300 dark:text-slate-600';
              if (isActive) {
                 if (isFailed) {
                     circleClass = 'bg-red-600 border-red-600 text-white shadow-lg shadow-red-100 dark:shadow-red-900/30';
                 } else {
                     circleClass = 'bg-blue-800 dark:bg-blue-600 border-blue-800 dark:border-blue-600 text-white shadow-lg shadow-blue-100 dark:shadow-blue-900/30';
                 }
              } else if (isCompleted) {
                 circleClass = 'bg-white dark:bg-slate-900 border-2 border-blue-800 dark:border-blue-600 text-blue-800 dark:text-blue-500';
              }

              return (
                <div key={step.id} className="relative flex flex-col items-center">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 z-10 ${circleClass}`}>
                    {isActive && !isFailed && step.id !== TransactionStatus.COMPLETED ? (
                        <Loader2 size={14} className="animate-spin" />
                    ) : (
                        <Icon size={14} />
                    )}
                  </div>
                  <span className={`absolute top-10 text-[10px] font-semibold whitespace-nowrap uppercase tracking-wider ${isActive ? 'text-slate-800 dark:text-slate-200' : 'text-slate-400 dark:text-slate-600'}`}>
                    {step.label}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Transaction Details - Statement Style */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg overflow-hidden">
            <div className="bg-slate-50/50 dark:bg-slate-800/50 px-4 py-2 border-b border-slate-200 dark:border-slate-800">
               <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Transaction Details</span>
            </div>
            <div className="divide-y divide-slate-100 dark:divide-slate-800">
                <div className="flex justify-between items-center px-4 py-3.5">
                    <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{t.status}</span>
                    <span className={`text-xs font-bold px-2 py-0.5 rounded ${isFailed ? 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-400' : 'bg-blue-50 dark:bg-blue-900/20 text-blue-800 dark:text-blue-300'}`}>
                        {transaction.status.replace(/_/g, ' ')}
                    </span>
                </div>
                <div className="flex justify-between items-center px-4 py-3.5">
                    <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{t.incoming}</span>
                    <span className="text-sm font-mono font-medium text-slate-900 dark:text-white">฿ {transaction.amountTHB.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                </div>
                <div className="flex justify-between items-center px-4 py-3.5">
                    <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{t.rate}</span>
                    <span className="text-xs font-mono text-slate-500 dark:text-slate-400">1 USDT = {transaction.rate.toFixed(2)} THB</span>
                </div>
                 <div className="flex justify-between items-center px-4 py-3.5 bg-slate-50/30 dark:bg-slate-800/30">
                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{t.outgoing}</span>
                    <span className="text-sm font-mono font-bold text-blue-800 dark:text-blue-400">{transaction.amountUSDT.toLocaleString(undefined, { minimumFractionDigits: 2 })} USDT</span>
                </div>
            </div>
        </div>

        {/* Dynamic Status Notification */}
        {transaction.status === TransactionStatus.VERIFYING_BANK && !isFailed && (
            <div className="mt-6 flex items-start gap-3 text-xs bg-blue-50 dark:bg-blue-900/10 p-4 rounded border border-blue-100 dark:border-blue-800">
                <Loader2 size={16} className="animate-spin text-blue-700 dark:text-blue-400 mt-0.5" />
                <div>
                   <p className="font-bold text-blue-800 dark:text-blue-300 mb-0.5">Bank Verification in Progress</p>
                   <p className="text-blue-600 dark:text-blue-400">{t.verifying}</p>
                </div>
            </div>
        )}
         {transaction.status === TransactionStatus.DISBURSING && !isFailed && (
            <div className="mt-6 flex items-start gap-3 text-xs bg-emerald-50 dark:bg-emerald-900/10 p-4 rounded border border-emerald-100 dark:border-emerald-800">
                <Wallet size={16} className="text-emerald-700 dark:text-emerald-400 mt-0.5" />
                <div>
                   <p className="font-bold text-emerald-800 dark:text-emerald-300 mb-0.5">Disbursement Initiated</p>
                   <p className="text-emerald-600 dark:text-emerald-400">{t.initiating}</p>
                </div>
            </div>
        )}
        {isFailed && (
            <div className="mt-6 flex items-start gap-3 text-xs bg-red-50 dark:bg-red-900/10 p-4 rounded border border-red-100 dark:border-red-800">
                <AlertTriangle size={16} className="text-red-700 dark:text-red-400 mt-0.5" />
                <div>
                   <p className="font-bold text-red-800 dark:text-red-300 mb-0.5">{t.alert}</p>
                   <p className="text-red-600 dark:text-red-400">{failureReason}</p>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Transaction, LogEntry, TransactionStatus, Language, AppConfig } from '../types';
import { MockBackend } from '../services/mockBackend';
import { ConfigService } from '../services/configService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { RefreshCw, Terminal, History, Settings, Save, Server } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

const data = [
  { name: '08:00', thb: 400000, usdt: 12000 },
  { name: '10:00', thb: 600000, usdt: 10000 },
  { name: '12:00', thb: 300000, usdt: 18000 },
  { name: '14:00', thb: 800000, usdt: 8000 },
  { name: '16:00', thb: 950000, usdt: 5000 },
];

interface Props {
  lang: Language;
  theme: 'light' | 'dark';
}

export const AdminDashboard: React.FC<Props> = ({ lang, theme }) => {
  const t = TRANSLATIONS[lang];
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [reserves, setReserves] = useState(MockBackend.getOrderBook());
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);
  const [history, setHistory] = useState<Transaction[]>([]);

  // Simulation inputs
  const [simName, setSimName] = useState('John Doe');
  const [simAmount, setSimAmount] = useState(1000);
  const [simError, setSimError] = useState<string | null>(null);

  // Global Config inputs
  const [config, setConfig] = useState<AppConfig>(ConfigService.get());
  const [editConfig, setEditConfig] = useState<AppConfig>(ConfigService.get());
  const [isConfigChanged, setIsConfigChanged] = useState(false);

  useEffect(() => {
    // Sync with backend simulation
    const interval = setInterval(() => {
      setLogs([...MockBackend.getLogs()]);
      setReserves({...MockBackend.getOrderBook()});
      setActiveTx(MockBackend.getCurrentTransaction());
      setHistory([...MockBackend.getTransactionHistory()]);

      const current = MockBackend.getCurrentTransaction();
      if (current) {
         if (simName === 'John Doe' && simAmount === 1000) {
            setSimName(current.user.fullName || 'John Doe');
            setSimAmount(current.amountTHB || 1000);
         }
      }
    }, 1000);

    const unsubscribeConfig = ConfigService.subscribe((newConfig) => {
        setConfig(newConfig);
    });

    return () => {
        clearInterval(interval);
        unsubscribeConfig();
    };
  }, [simName, simAmount]);

  const triggerWebhook = () => {
    setSimError(null);
    if (!activeTx) { setSimError(t.errNoTx); return; }
    if (!simName || simName.trim().length === 0) { setSimError(t.errSenderName); return; }
    if (simAmount <= 0 || isNaN(simAmount)) { setSimError(t.errAmount); return; }
    MockBackend.triggerIncomingTransfer(simAmount, simName, activeTx.referenceId);
  };

  const toggleHedge = () => {
    MockBackend.toggleAutoHedge();
    setReserves({...MockBackend.getOrderBook()});
  };

  const handleConfigChange = (key: keyof AppConfig, value: string | number) => {
    setEditConfig(prev => ({...prev, [key]: value}));
    setIsConfigChanged(true);
  };

  const saveConfig = () => {
    ConfigService.update(editConfig);
    setIsConfigChanged(false);
  };

  const completedHistory = history.filter(tx => 
    tx.status === TransactionStatus.COMPLETED || tx.status === TransactionStatus.FAILED
  );

  return (
    <div className={`mt-12 ${THEME.card} overflow-hidden`}>
      {/* Admin Header */}
      <div className="bg-slate-50 dark:bg-slate-900 p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
         <div className="flex items-center gap-2">
            <Server size={18} className="text-slate-500 dark:text-slate-400" />
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200">{t.adminConsole}</h3>
         </div>
         <span className="text-[10px] font-mono text-blue-700 dark:text-blue-300 bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded border border-blue-200 dark:border-blue-800">{t.secAudit}</span>
      </div>

      <div className="p-6 bg-white dark:bg-slate-950 grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Metrics & Controls */}
        <div className="lg:col-span-2 space-y-6">

            {/* Metric Cards */}
            <div className="grid grid-cols-3 gap-4">
                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded shadow-sm">
                    <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase font-bold">{t.thbReserves}</p>
                    <p className="text-lg font-mono text-green-600 dark:text-green-400 font-bold">฿{reserves.thbReserves.toLocaleString()}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded shadow-sm">
                    <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase font-bold">{t.usdtFloat}</p>
                    <p className="text-lg font-mono text-blue-600 dark:text-blue-400 font-bold">
                        {reserves.usdtReserves.toLocaleString()} <span className="text-xs text-slate-400 dark:text-slate-500 font-normal">USDT</span>
                    </p>
                </div>
                 <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded shadow-sm flex flex-col justify-center">
                    <div className="flex items-center justify-between">
                         <span className="text-[10px] text-slate-500 dark:text-slate-400 uppercase font-bold">{t.autoHedge}</span>
                         <div className={`w-2 h-2 rounded-full ${reserves.autoHedge ? 'bg-green-500' : 'bg-slate-400'}`}></div>
                    </div>
                    <button 
                        onClick={toggleHedge} 
                        className="mt-1 text-[10px] bg-white hover:bg-slate-50 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 py-1 px-2 rounded border border-slate-300 dark:border-slate-700 w-full transition-colors"
                    >
                        Toggle Status
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                {/* Configuration Panel */}
                <div className="border border-slate-200 dark:border-slate-800 rounded bg-slate-50/50 dark:bg-slate-900/50">
                     <div className="p-3 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 rounded-t">
                        <span className="text-xs font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                           <Settings size={12} /> {t.globalSettings}
                        </span>
                        {isConfigChanged && (
                            <button onClick={saveConfig} className="text-[10px] bg-blue-700 text-white px-2 py-0.5 rounded flex items-center gap-1 shadow-sm hover:bg-blue-600">
                                <Save size={10} /> {t.save}
                            </button>
                        )}
                     </div>
                     <div className="p-3 space-y-2 bg-white dark:bg-slate-900 rounded-b">
                         <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold">{t.lblBaseRate}</label>
                                <input type="number" step="0.01" value={editConfig.baseRate} onChange={(e) => handleConfigChange('baseRate', parseFloat(e.target.value))} className={THEME.input + " h-8 text-xs"} />
                            </div>
                            <div>
                                <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold">{t.lblServiceFee}</label>
                                <input type="number" step="0.1" value={editConfig.feePercent} onChange={(e) => handleConfigChange('feePercent', parseFloat(e.target.value))} className={THEME.input + " h-8 text-xs"} />
                            </div>
                         </div>
                         <div>
                            <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold">{t.lblMerchantId}</label>
                            <input type="text" value={editConfig.promptPayId} onChange={(e) => handleConfigChange('promptPayId', e.target.value)} className={THEME.input + " h-8 text-xs font-mono"} />
                         </div>
                     </div>
                </div>

                {/* Chart */}
                <div className="border border-slate-200 dark:border-slate-800 rounded bg-white dark:bg-slate-900 p-2 h-[180px] shadow-sm">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data}>
                            <XAxis dataKey="name" stroke={theme === 'dark' ? '#94a3b8' : '#64748b'} fontSize={9} />
                            <YAxis stroke={theme === 'dark' ? '#94a3b8' : '#64748b'} fontSize={9} />
                            <Tooltip 
