         <div className="flex items-center gap-2">
            <Server size={18} className="text-slate-500 dark:text-slate-400" />
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200">{t.adminConsole}</h3>
         </div>
         <span className="text-[10px] font-mono text-blue-700 dark:text-blue-300 bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded border border-blue-200 dark:border-blue-800">{t.secAudit}</span>
      </div>

      <div className="p-6 bg-white dark:bg-slate-950 grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Metrics & Controls */}
