              >
                  <Globe size={12} />
                  {lang === 'en' ? 'EN' : 'TH'}
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full p-6 md:py-12 space-y-10">

        {/* Screen 1: Swap Interface (Bank Transfer Style) */}
        {screen === 'SWAP' && (
          <div className="max-w-2xl mx-auto">
