import React, { useState } from 'react';
import { Transaction, TransactionStatus, Language } from '../types';
import { Check, Loader2, Wallet, ArrowLeftRight, Server, AlertTriangle, FileText, Clock, ChevronDown, ChevronUp, XCircle } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

interface Props {
  transaction: Transaction;
  lang: Language;
}

export const TransactionPulse: React.FC<Props> = ({ transaction, lang }) => {
  const t = TRANSLATIONS[lang];
  const [showLogs, setShowLogs] = useState(false);
  const isFailed = transaction.status === TransactionStatus.FAILED;

  const steps = [
    { id: TransactionStatus.AWAITING_PAYMENT, label: t.stepPayment },
    { id: TransactionStatus.VERIFYING_BANK, label: t.stepBank },
    { id: TransactionStatus.DISBURSING, label: t.stepDisburse },
    { id: TransactionStatus.COMPLETED, label: t.stepComplete },
  ];

  const getCurrentStepIndex = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.AWAITING_PAYMENT: return 0;
      case TransactionStatus.VERIFYING_BANK: return 1;
      case TransactionStatus.DISBURSING: return 2;
      case TransactionStatus.COMPLETED: return 3;
      case TransactionStatus.FAILED: return 1; 
      default: return 0;
    }
  };

  const currentStep = getCurrentStepIndex(transaction.status);

  const failureReason = isFailed 
    ? (transaction.logs.find(l => l.level === 'CRITICAL')?.message || 'Compliance checks failed.') 
    : null;

  return (
    <div className={`w-full max-w-3xl mx-auto ${THEME.card} overflow-hidden shadow-formal ${isFailed ? 'border-red-200 dark:border-red-900/50' : ''}`}>
      {/* Formal Header with Receipt styling */}
      <div className={`px-6 py-4 border-b flex justify-between items-center ${isFailed ? 'bg-red-50 dark:bg-red-900/10 border-red-100 dark:border-red-900/30' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800'}`}>
         <div className="flex items-center gap-3">
            <div className={`p-1.5 border rounded-sm shadow-sm ${isFailed ? 'bg-red-100 dark:bg-red-900/30 border-red-200 dark:border-red-800 text-red-600 dark:text-red-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400'}`}>
               {isFailed ? <AlertTriangle size={16} /> : <FileText size={16} />}
            </div>
            <div>
               <h2 className={`text-xs font-bold uppercase tracking-widest ${isFailed ? 'text-red-800 dark:text-red-200' : 'text-slate-800 dark:text-slate-200'}`}>
                 {isFailed ? t.txFailed : t.txPulse}
               </h2>
               <p className={`text-[10px] font-mono mt-0.5 tracking-wide ${isFailed ? 'text-red-600/70 dark:text-red-400/70' : 'text-slate-500 dark:text-slate-400'}`}>REF: {transaction.referenceId}</p>
            </div>
         </div>
         <div className={`px-2 py-0.5 rounded-sm text-[10px] font-bold border ${isFailed ? 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 border-red-200 dark:border-red-800' : 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800'}`}>
             {isFailed ? t.rejected : t.secure}
         </div>
      </div>

      <div className="p-6 md:p-8 bg-white dark:bg-slate-950">
        {/* Horizontal Stepper */}
        <div className="mb-10 px-4">
            <div className="flex items-center justify-between relative">
                {/* Connecting Line */}
                <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-0.5 bg-slate-100 dark:bg-slate-800 -z-10"></div>
                <div 
                    className={`absolute left-0 top-1/2 -translate-y-1/2 h-0.5 transition-all duration-700 -z-10 ${isFailed ? 'bg-red-200 dark:bg-red-900/30' : 'bg-blue-900 dark:bg-blue-600'}`}
                    style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }}
                ></div>

                {steps.map((step, index) => {
                    const isActive = index === currentStep;
                    const isCompleted = index < currentStep;

                    let dotClass = "bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-700";
                    let textClass = "text-slate-400 dark:text-slate-600";

                    if (isActive) {
                        dotClass = isFailed 
                            ? "bg-white dark:bg-slate-900" // Placeholder, we use Icon
                            : "bg-blue-900 dark:bg-blue-600 border-blue-900 dark:border-blue-600 shadow-sm";
                        textClass = "text-blue-900 dark:text-white font-bold";
                        if (isFailed) textClass = "text-red-700 dark:text-red-400 font-bold";
                    } else if (isCompleted) {
                        dotClass = "bg-blue-900 dark:bg-blue-600 border-blue-900 dark:border-blue-600";
                        textClass = "text-slate-600 dark:text-slate-400 font-medium";
                    }

                    return (
                        <div key={step.id} className="flex flex-col items-center gap-2 bg-white dark:bg-slate-950 px-2 relative z-10">
                             {isActive && isFailed ? (
                                <XCircle size={14} className="text-red-600 dark:text-red-500 bg-white dark:bg-slate-950 rounded-full" />
                             ) : (
                                <div className={`w-3 h-3 rounded-full ${dotClass} transition-colors duration-300`}></div>
                             )}
                             <span className={`text-[10px] uppercase tracking-wider ${textClass}`}>{step.label}</span>
                        </div>
                    )
                })}
            </div>
        </div>

        {/* Failed Status Message Block */}
        {isFailed && (
            <div className="mb-8 flex items-start gap-4 p-4 rounded-md bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/50 shadow-sm animate-pulse">
                <div className="bg-red-100 dark:bg-red-800/30 p-2 rounded-full shrink-0 border border-red-200 dark:border-red-700/50">
                    <AlertTriangle size={20} className="text-red-600 dark:text-red-400" />
                </div>
                <div>
                   <h3 className="text-sm font-bold text-red-800 dark:text-red-300 uppercase tracking-wide mb-1">{t.alert}</h3>
                   <p className="text-sm text-red-700 dark:text-red-300 font-medium mb-3">{failureReason}</p>
                   <div className="flex gap-2">
                      <span className="text-[10px] font-mono text-red-600/80 dark:text-red-400/80 bg-red-100/50 dark:bg-red-900/30 px-2 py-1 rounded border border-red-100 dark:border-red-800/50">
                         ERR_CODE: 0x{transaction.referenceId.slice(-4)}
                      </span>
                   </div>
                </div>
            </div>
        )}

        {/* Transaction Details - Statement Style */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-sm overflow-hidden mb-6">
            <div className="bg-slate-50 dark:bg-slate-900 px-4 py-2 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center">
               <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Transaction Details</span>
               <span className="text-[10px] font-mono text-slate-400">{new Date(transaction.timestamp).toLocaleString()}</span>
            </div>
            <table className="w-full text-xs">
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                    <tr>
                         <td className="px-4 py-3 text-slate-500 dark:text-slate-400 font-medium w-1/3">{t.status}</td>
                         <td className="px-4 py-3 text-right">
                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-sm uppercase tracking-wide ${isFailed ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-800'}`}>
                                {transaction.status.replace(/_/g, ' ')}
                            </span>
                         </td>
                    </tr>
                    {transaction.memo && (
                        <tr>
                            <td className="px-4 py-3 text-slate-500 dark:text-slate-400 font-medium">Ref / Memo</td>
                            <td className="px-4 py-3 text-right font-mono text-slate-700 dark:text-slate-300 italic">{transaction.memo}</td>
                        </tr>
                    )}
                    <tr>
                         <td className="px-4 py-3 text-slate-500 dark:text-slate-400 font-medium">{t.incoming}</td>
                         <td className="px-4 py-3 text-right font-mono font-medium text-slate-900 dark:text-white">฿ {transaction.amountTHB.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                    </tr>
                    <tr>
                         <td className="px-4 py-3 text-slate-500 dark:text-slate-400 font-medium">{t.rate}</td>
                         <td className="px-4 py-3 text-right font-mono text-slate-500 dark:text-slate-400">1 USDT = {transaction.rate.toFixed(2)} THB</td>
                    </tr>
                    <tr className="bg-slate-50/50 dark:bg-slate-800/20">
                         <td className="px-4 py-3 text-slate-800 dark:text-slate-300 font-bold">{t.outgoing}</td>
                         <td className="px-4 py-3 text-right font-mono font-bold text-blue-900 dark:text-blue-400">{transaction.amountUSDT.toLocaleString(undefined, { minimumFractionDigits: 2 })} USDT</td>
                    </tr>
                </tbody>
            </table>
        </div>

        {/* Live Status Message (Only if active) */}
        {transaction.status === TransactionStatus.VERIFYING_BANK && !isFailed && (
            <div className="flex items-center gap-3 text-xs bg-blue-50 dark:bg-blue-900/10 p-3 rounded-sm border-l-2 border-blue-600 dark:border-blue-500">
                <Loader2 size={14} className="animate-spin text-blue-700 dark:text-blue-400" />
                <span className="text-blue-800 dark:text-blue-300 font-medium">{t.verifying}</span>
            </div>
        )}
         {transaction.status === TransactionStatus.DISBURSING && !isFailed && (
            <div className="flex items-center gap-3 text-xs bg-blue-50 dark:bg-blue-900/10 p-3 rounded-sm border-l-2 border-blue-600 dark:border-blue-500">
                <Wallet size={14} className="text-blue-700 dark:text-blue-400" />
                <span className="text-blue-800 dark:text-blue-300 font-medium">{t.initiating}</span>
            </div>
        )}

        {/* Collapsible Logs Section */}
        <div className="mt-8 border-t border-slate-100 dark:border-slate-800 pt-4">
            <button 
                onClick={() => setShowLogs(!showLogs)}
                className="flex items-center gap-2 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest hover:text-blue-800 dark:hover:text-blue-400 transition-colors"
            >
                {showLogs ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
                Audit Logs ({transaction.logs.length})
            </button>

            {showLogs && (
                <div className="mt-4 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-sm p-3 max-h-48 overflow-y-auto custom-scrollbar">
                     <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="text-[9px] text-slate-400 dark:text-slate-500 uppercase border-b border-slate-200 dark:border-slate-800">
                                <th className="pb-2 pl-1 font-semibold w-24">Time</th>
                                <th className="pb-2 font-semibold w-20">Level</th>
                                <th className="pb-2 font-semibold w-24">Module</th>
                                <th className="pb-2 font-semibold">Message</th>
                            </tr>
                        </thead>
                        <tbody className="font-mono text-[9px]">
                            {transaction.logs.map((log, idx) => (
                                <tr key={idx} className="border-b border-slate-100 dark:border-slate-800/50 last:border-0 hover:bg-slate-100 dark:hover:bg-slate-800/50 transition-colors">
                                    <td className="py-1.5 pl-1 text-slate-500 dark:text-slate-400 whitespace-nowrap">{log.timestamp.split('T')[1].split('.')[0]}</td>
                                    <td className="py-1.5">
                                        <span className={`px-1 rounded-sm font-bold ${
                                            log.level === 'CRITICAL' ? 'text-red-700 bg-red-50 dark:bg-red-900/20' :
                                            log.level === 'WARN' ? 'text-amber-700 bg-amber-50 dark:bg-amber-900/20' :
                                            'text-blue-700 bg-blue-50 dark:bg-blue-900/20'
                                        }`}>
                                            {log.level}
                                        </span>
                                    </td>
                                    <td className="py-1.5 text-slate-600 dark:text-slate-300 font-semibold">{log.module}</td>
                                    <td className="py-1.5 text-slate-600 dark:text-slate-300">{log.message}</td>
                                </tr>
                            ))}
                        </tbody>
                     </table>
                     {transaction.logs.length === 0 && <p className="text-[9px] text-slate-400 text-center italic py-2">No logs generated yet.</p>}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Transaction, LogEntry, TransactionStatus, Language, AppConfig } from '../types';
import { MockBackend } from '../services/mockBackend';
import { ConfigService } from '../services/configService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { RefreshCw, Terminal, History, Settings, Save, Server, Wallet, Link as LinkIcon, ExternalLink, Check, Activity, DollarSign, Percent, Smartphone } from 'lucide-react';
import { THEME, TRANSLATIONS } from '../constants';

const data = [
  { name: '08:00', thb: 400000, usdt: 12000 },
  { name: '10:00', thb: 600000, usdt: 10000 },
  { name: '12:00', thb: 300000, usdt: 18000 },
  { name: '14:00', thb: 800000, usdt: 8000 },
  { name: '16:00', thb: 950000, usdt: 5000 },
];

interface Props {
  lang: Language;
  theme: 'light' | 'dark';
  onSimulateDeepLink?: (amount: number, memo?: string) => void;
}

export const AdminDashboard: React.FC<Props> = ({ lang, theme, onSimulateDeepLink }) => {
  const t = TRANSLATIONS[lang];
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [reserves, setReserves] = useState(MockBackend.getOrderBook());
  const [activeTx, setActiveTx] = useState<Transaction | null>(null);
  const [history, setHistory] = useState<Transaction[]>([]);

  // Simulation inputs
  const [simName, setSimName] = useState('John Doe');
  const [simAmount, setSimAmount] = useState(1000);
  const [simError, setSimError] = useState<string | null>(null);

  // Link Generator inputs
  const [linkAmount, setLinkAmount] = useState(5000);
  const [linkMemo, setLinkMemo] = useState('');
  const [generatedLink, setGeneratedLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);

  // Global Config inputs
  const [config, setConfig] = useState<AppConfig>(ConfigService.get());
  const [editConfig, setEditConfig] = useState<AppConfig>(ConfigService.get());
  const [isConfigChanged, setIsConfigChanged] = useState(false);

  useEffect(() => {
    // Sync with backend simulation
    const interval = setInterval(() => {
      setLogs([...MockBackend.getLogs()]);
      setReserves({...MockBackend.getOrderBook()});
      setActiveTx(MockBackend.getCurrentTransaction());
      setHistory([...MockBackend.getTransactionHistory()]);

      const current = MockBackend.getCurrentTransaction();
      if (current) {
         if (simName === 'John Doe' && simAmount === 1000) {
            setSimName(current.user.fullName || 'John Doe');
            setSimAmount(current.amountTHB || 1000);
         }
      }
    }, 1000);

    const unsubscribeConfig = ConfigService.subscribe((newConfig) => {
        setConfig(newConfig);
        if (!isConfigChanged) {
           setEditConfig(newConfig);
        }
    });

    return () => {
        clearInterval(interval);
        unsubscribeConfig();
    };
  }, [simName, simAmount, isConfigChanged]);

  useEffect(() => {
    // Robust link generation: Use current origin + pathname to ensure it works on any host/subpath
    // Avoid /pay sub-route to prevent 404s on static hosts without SPA routing config
    const baseUrl = window.location.origin + window.location.pathname;
    const params = new URLSearchParams();
    params.set('amt', linkAmount.toString());
    if (linkMemo && linkMemo.trim() !== '') {
        params.set('ref', linkMemo.trim());
    }
    setGeneratedLink(`${baseUrl}?${params.toString()}`);
  }, [linkAmount, linkMemo]);

  const triggerWebhook = () => {
    setSimError(null);
    if (!activeTx) { setSimError(t.errNoTx); return; }
    if (!simName || simName.trim().length === 0) { setSimError(t.errSenderName); return; }
    if (simAmount <= 0 || isNaN(simAmount)) { setSimError(t.errAmount); return; }
    MockBackend.triggerIncomingTransfer(simAmount, simName, activeTx.referenceId);
  };

  const toggleHedge = () => {
    MockBackend.toggleAutoHedge();
    setReserves({...MockBackend.getOrderBook()});
  };

  const handleConfigChange = (key: keyof AppConfig, value: string | number) => {
    setEditConfig(prev => ({...prev, [key]: value}));
    setIsConfigChanged(true);
  };

  const saveConfig = () => {
    ConfigService.update(editConfig);
    setIsConfigChanged(false);
  };

  const handleCopyLink = () => {
    if (generatedLink) {
      navigator.clipboard.writeText(generatedLink);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const completedHistory = history.filter(tx => 
    tx.status === TransactionStatus.COMPLETED || tx.status === TransactionStatus.FAILED
  );

  return (
    <div className={`mt-12 ${THEME.card} overflow-hidden`}>
      {/* Admin Header */}
      <div className="bg-slate-900 text-white p-3 border-b border-slate-800 flex items-center justify-between">
         <div className="flex items-center gap-2">
            <Server size={14} className="text-slate-400" />
            <h3 className="text-xs font-bold uppercase tracking-widest">{t.adminConsole}</h3>
         </div>
         <span className="text-[9px] font-mono text-emerald-400 bg-emerald-900/30 px-2 py-0.5 rounded border border-emerald-900">{t.secAudit}</span>
      </div>

      <div className="p-4 bg-slate-100 dark:bg-slate-950 grid grid-cols-1 lg:grid-cols-3 gap-4">

        {/* Left Column: Metrics & Controls */}
        <div className="lg:col-span-2 space-y-4">

            {/* Metric Cards - Dense */}
            <div className="grid grid-cols-3 gap-3">
                <div className="bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-800 p-3 rounded-sm shadow-sm">
                    <p className="text-[9px] text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">{t.thbReserves}</p>
                    <p className="text-sm font-mono text-slate-800 dark:text-slate-200 font-bold mt-1">฿{reserves.thbReserves.toLocaleString()}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-800 p-3 rounded-sm shadow-sm">
                    <p className="text-[9px] text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">{t.usdtFloat}</p>
                    <p className="text-sm font-mono text-blue-800 dark:text-blue-400 font-bold mt-1">
                        {reserves.usdtReserves.toLocaleString()} <span className="text-[9px] text-slate-400 font-normal">USDT</span>
                    </p>
                </div>
                 <div className="bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-800 p-3 rounded-sm shadow-sm flex flex-col justify-center">
                    <div className="flex items-center justify-between">
                         <span className="text-[9px] text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">{t.autoHedge}</span>
                         <div className={`w-1.5 h-1.5 rounded-full ${reserves.autoHedge ? 'bg-emerald-500' : 'bg-slate-400'}`}></div>
                    </div>
                    <button 
                        onClick={toggleHedge} 
                        className="mt-2 text-[9px] bg-slate-50 hover:bg-slate-100 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 py-0.5 px-2 rounded-sm border border-slate-200 dark:border-slate-700 w-full transition-colors font-medium uppercase"
                    >
                        {reserves.autoHedge ? 'Disable' : 'Enable'}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                {/* Configuration Panel */}
                <div className="border border-slate-300 dark:border-slate-800 rounded-sm bg-white dark:bg-slate-900 shadow-sm flex flex-col">
                     <div className="p-2 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                        <span className="text-[10px] font-bold text-slate-700 dark:text-slate-300 flex items-center gap-1 uppercase">
                           <Settings size={10} /> {t.globalSettings}
                        </span>
                        {isConfigChanged && (
                            <button onClick={saveConfig} className="text-[9px] bg-blue-900 hover:bg-blue-800 text-white px-2 py-0.5 rounded-sm flex items-center gap-1 shadow-sm uppercase font-bold animate-pulse transition-colors">
                                <Save size={8} /> {t.save}
                            </button>
                        )}
                     </div>
                     <div className="p-3 space-y-3">
                         <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold flex items-center gap-1">
                                    <DollarSign size={8} /> {t.lblBaseRate}
                                </label>
                                <input 
                                    type="number" 
                                    step="0.01" 
                                    value={editConfig.baseRate} 
                                    onChange={(e) => handleConfigChange('baseRate', parseFloat(e.target.value))} 
                                    className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm bg-slate-50 dark:bg-slate-950 focus:bg-white dark:focus:bg-slate-900 focus:border-blue-500 outline-none transition-colors" 
                                />
                            </div>
                            <div>
                                <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold flex items-center gap-1">
                                    <Percent size={8} /> {t.lblServiceFee}
                                </label>
                                <input 
                                    type="number" 
                                    step="0.1" 
                                    value={editConfig.feePercent} 
                                    onChange={(e) => handleConfigChange('feePercent', parseFloat(e.target.value))} 
                                    className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm bg-slate-50 dark:bg-slate-950 focus:bg-white dark:focus:bg-slate-900 focus:border-blue-500 outline-none transition-colors" 
                                />
                            </div>
                         </div>
                         <div>
                            <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold flex items-center gap-1">
                                <Smartphone size={8} /> {t.lblMerchantId}
                            </label>
                            <input 
                                type="text" 
                                value={editConfig.promptPayId} 
                                onChange={(e) => handleConfigChange('promptPayId', e.target.value)} 
                                className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm bg-slate-50 dark:bg-slate-950 focus:bg-white dark:focus:bg-slate-900 focus:border-blue-500 outline-none transition-colors font-mono" 
                            />
                         </div>
                         <div>
                            <label className="text-[9px] text-slate-500 dark:text-slate-400 uppercase block mb-1 font-bold flex items-center gap-1">
                                <Wallet size={8} /> {t.lblWallet}
                            </label>
                            <input 
                                type="text" 
                                value={editConfig.providerWallet} 
                                onChange={(e) => handleConfigChange('providerWallet', e.target.value)} 
                                className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm bg-slate-50 dark:bg-slate-950 focus:bg-white dark:focus:bg-slate-900 focus:border-blue-500 outline-none transition-colors font-mono" 
                            />
                         </div>
                     </div>
                </div>

                {/* Chart */}
                <div className="border border-slate-300 dark:border-slate-800 rounded-sm bg-white dark:bg-slate-900 p-2 h-[180px] shadow-sm">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data}>
                            <XAxis dataKey="name" stroke={theme === 'dark' ? '#94a3b8' : '#64748b'} fontSize={9} />
                            <YAxis stroke={theme === 'dark' ? '#94a3b8' : '#64748b'} fontSize={9} />
                            <Tooltip 
                                cursor={{fill: 'transparent'}}
                                contentStyle={{ 
                                    backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', 
                                    borderColor: theme === 'dark' ? '#334155' : '#e2e8f0',
                                    fontSize: '10px', 
                                    color: theme === 'dark' ? '#f8fafc' : '#0f172a',
                                    borderRadius: '2px'
                                }} 
                            />
                            <Bar dataKey="thb" fill={theme === 'dark' ? '#10b981' : '#059669'} />
                            <Bar dataKey="usdt" fill={theme === 'dark' ? '#3b82f6' : '#1e40af'} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Webhook Tool */}
                <div className="border border-slate-300 dark:border-slate-800 rounded-sm p-3 bg-white dark:bg-slate-900 shadow-sm flex flex-col justify-between">
                    <div>
                        <p className="text-[9px] text-slate-500 dark:text-slate-400 uppercase font-bold mb-2 flex items-center gap-1">
                            <Activity size={10} /> {t.webhookSim}
                        </p>
                        <div className="space-y-2">
                            <input type="text" value={simName} onChange={(e) => setSimName(e.target.value)} className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm" placeholder={t.senderNamePlaceholder} />
                            <input type="number" value={simAmount} onChange={(e) => setSimAmount(Number(e.target.value))} className="w-full h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm" placeholder={t.amountPlaceholder} />
                        </div>
                    </div>
                    <div className="mt-2">
                        <button onClick={triggerWebhook} className="w-full bg-slate-800 hover:bg-slate-700 dark:bg-slate-700 dark:hover:bg-slate-600 text-white px-3 py-1 rounded-sm text-[10px] h-7 whitespace-nowrap font-bold uppercase transition-colors">
                            {t.triggerWebhook}
                        </button>
                        {simError && <p className="text-[9px] text-red-600 dark:text-red-400 mt-1 font-medium">{simError}</p>}
                    </div>
                </div>

                {/* Payment Link Generator */}
                <div className="border border-slate-300 dark:border-slate-800 rounded-sm p-3 bg-white dark:bg-slate-900 shadow-sm flex flex-col justify-between">
                     <div>
                         <p className="text-[9px] text-slate-500 dark:text-slate-400 uppercase font-bold mb-2 flex items-center gap-1">
                             <LinkIcon size={10} /> {t.paymentLink}
                         </p>
                         <div className="space-y-2">
                             <div className="flex gap-2">
                                <input 
                                    type="number" 
                                    value={linkAmount} 
                                    onChange={(e) => setLinkAmount(Number(e.target.value))} 
                                    className="w-20 h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm" 
                                    placeholder="Amt" 
                                />
                                <input 
                                    type="text" 
                                    value={linkMemo} 
                                    onChange={(e) => setLinkMemo(e.target.value)} 
                                    className="flex-1 h-7 text-[10px] px-2 border border-slate-300 dark:border-slate-700 rounded-sm" 
                                    placeholder={t.lblMemo} 
                                />
                             </div>
                             <div className="relative">
                                 <input readOnly value={generatedLink} className="w-full h-7 text-[9px] bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-sm px-2 text-slate-500 font-mono" />
                             </div>
                         </div>
                     </div>
                     <div className="mt-2 flex gap-2">
                         <button 
                            onClick={handleCopyLink}
                            className={`flex-1 border ${isCopied ? 'bg-emerald-50 border-emerald-300 text-emerald-700' : 'bg-white border-slate-300 text-slate-600'} dark:bg-slate-800 dark:border-slate-700 dark:text-slate-300 px-3 py-1 rounded-sm text-[10px] h-7 font-bold uppercase transition-colors flex items-center justify-center gap-1`}
                        >
                            {isCopied ? <Check size={10} /> : <LinkIcon size={10} />} {isCopied ? 'Copied' : t.genLink}
                         </button>
                         <button 
                            onClick={() => onSimulateDeepLink && onSimulateDeepLink(linkAmount, linkMemo)}
                            className="flex-1 bg-blue-900 hover:bg-blue-800 text-white px-3 py-1 rounded-sm text-[10px] h-7 font-bold uppercase transition-colors flex items-center justify-center gap-1"
                         >
                            <ExternalLink size={10} /> {t.testLink}
                         </button>
                     </div>
                </div>
            </div>
        </div>

        {/* Right Column: Logs */}
        <div className="border border-slate-300 dark:border-slate-800 rounded-sm bg-white dark:bg-slate-900 flex flex-col h-[400px] lg:h-auto overflow-hidden">
            <div className="p-2 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900">
                <span className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase flex items-center gap-1">
                    <Terminal size={10} /> {t.sysLogs}
                </span>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-1 font-mono text-[9px] bg-white dark:bg-slate-950 custom-scrollbar">
                {logs.length === 0 && <p className="text-slate-400 dark:text-slate-600 text-center mt-4 italic">No Activity</p>}
                {logs.map((log, i) => (
                    <div key={i} className="flex gap-2 border-b border-slate-100 dark:border-slate-800/50 pb-1 mb-1 last:border-0">
                        <span className="text-slate-400 dark:text-slate-600 shrink-0">{log.timestamp.split('T')[1].split('.')[0]}</span>
                        <span className={
                            log.level === 'CRITICAL' ? 'text-red-700 dark:text-red-400 font-bold' :
                            log.level === 'WARN' ? 'text-amber-700 dark:text-amber-400' : 'text-slate-700 dark:text-slate-300'
                        }>
                            <span className="font-bold opacity-70">[{log.module}]</span> {log.message}
                        </span>
                    </div>
                ))}
            </div>
        </div>
      </div>

      {/* History Table */}
      <div className="border-t border-slate-300 dark:border-slate-800 mt-4 pt-0">
         <div className="p-2 bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
             <h4 className="text-[10px] font-bold text-slate-600 dark:text-slate-300 flex items-center gap-2 uppercase">
                <History size={10} /> {t.txHistory}
             </h4>
         </div>
         <div className="overflow-x-auto bg-white dark:bg-slate-950">
             <table className="w-full text-xs text-left">
                <thead className="text-[9px] text-slate-500 dark:text-slate-400 uppercase bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                   <tr>
                      <th className="px-4 py-2 font-bold">{t.colRef}</th>
                      <th className="px-4 py-2 font-bold">{t.colAmtThb}</th>
                      <th className="px-4 py-2 font-bold">{t.colAmtUsdt}</th>
                      <th className="px-4 py-2 font-bold">{t.colStatus}</th>
