                         <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                            <td className="px-4 py-2 font-mono text-slate-600 dark:text-slate-300">
                                {tx.referenceId}
                                {tx.memo && <span className="block text-[8px] text-slate-400 italic">Ref: {tx.memo}</span>}
                            </td>
                            <td className="px-4 py-2 font-mono text-emerald-700 dark:text-emerald-400 font-bold">฿{tx.amountTHB.toLocaleString()}</td>
                            <td className="px-4 py-2 font-mono text-blue-800 dark:text-blue-400 font-bold">
                                {tx.amountUSDT.toLocaleString()} <span className="text-[9px] text-slate-400 font-normal">USDT</span>
                            </td>
                            <td className="px-4 py-2">
                               <span className={`text-[8px] px-1.5 py-0.5 rounded-sm font-bold border uppercase ${
                                   tx.status === TransactionStatus.COMPLETED 
                                   ? 'text-emerald-800 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800 bg-emerald-50 dark:bg-emerald-900/20' 
                                   : 'text-red-800 dark:text-red-400 border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20'
                               }`}>
                                  {tx.status}
                               </span>
                            </td>
                            <td className="px-4 py-2 text-slate-500 dark:text-slate-400 font-mono">{new Date(tx.timestamp).toLocaleString()}</td>
                         </tr>
                       ))
                   )}
                </tbody>
             </table>
         </div>
      </div>
    </div>
  );
};

export enum TransactionStatus {
  IDLE = 'IDLE',
  KYC_PENDING = 'KYC_PENDING',
  AWAITING_PAYMENT = 'AWAITING_PAYMENT',
  VERIFYING_BANK = 'VERIFYING_BANK', // Logic Guard
  DISBURSING = 'DISBURSING', // Crypto Transfer
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export type Language = 'en' | 'th';

export interface UserKYC {
  fullName: string;
  nationalId: string; // Thai ID or Passport
  walletAddress: string;
  isVerified: boolean;
}

export interface Transaction {
  id: string;
  referenceId: string; // For bank reconciliation
  user: UserKYC;
  amountTHB: number;
  amountUSDT: number;
  rate: number;
  status: TransactionStatus;
  timestamp: number;
  qrPayload?: string;
  logs: LogEntry[];
  memo?: string;
}

export interface LogEntry {
  timestamp: string;
  level: 'INFO' | 'WARN' | 'CRITICAL';
  module: 'WEBHOOK' | 'KYC' | 'LEDGER' | 'DISBURSER';
  message: string;
  hash: string; // Simulated hash of the log for integrity
}

export interface OrderBook {
  thbReserves: number;
  usdtReserves: number;
  autoHedge: boolean;
  spread: number;
}

export interface AppConfig {
  baseRate: number;
  feePercent: number; // Stored as percentage (e.g. 0.8 for 0.8%)
  promptPayId: string;
  providerWallet: string;
  defaultAmountTHB: number;
}

import { BASE_RATE, SPREAD_PERCENT, PROMPTPAY_ID } from '../constants';
import { AppConfig } from '../types';

const STORAGE_KEY = 'promptpay_gateway_config';

const DEFAULT_CONFIG: AppConfig = {
  baseRate: BASE_RATE,
  feePercent: SPREAD_PERCENT * 100, // Convert 0.008 to 0.8 for display/editing
  promptPayId: PROMPTPAY_ID,
  providerWallet: "TWd4...SimulatedProviderHotWallet",
  defaultAmountTHB: 1000
};

// Helper to load from storage
const loadConfig = (): AppConfig => {
  if (typeof window === 'undefined') return DEFAULT_CONFIG;
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
    }
  } catch (e) {
    console.warn("Failed to load config from storage:", e);
  }
  return DEFAULT_CONFIG;
};

let currentConfig: AppConfig = loadConfig();
let listeners: ((config: AppConfig) => void)[] = [];

export const ConfigService = {
  // Get current snapshot
  get: () => ({ ...currentConfig }),

  // Update specific fields, save to storage, and notify listeners
  update: (updates: Partial<AppConfig>) => {
    currentConfig = { ...currentConfig, ...updates };
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(currentConfig));
    } catch (e) {
      console.warn("Failed to save config to storage:", e);
    }
    listeners.forEach(l => l(currentConfig));
  },

  // Reset to default constants
  reset: () => {
    currentConfig = { ...DEFAULT_CONFIG };
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      console.warn("Failed to clear config storage:", e);
    }
    listeners.forEach(l => l(currentConfig));
  },

  // Subscribe to changes
  subscribe: (callback: (config: AppConfig) => void) => {
    listeners.push(callback);
    callback(currentConfig); // Fire immediately with current state
    return () => {
      listeners = listeners.filter(l => l !== callback);
    };
  }
};

